  var st=document.createElement('style'); st.textContent="/* Layout: one featured card, today's Aliyah on top; a 7-day strip shows where we are in the week. Colours follow thewayderech.co.za (red + charcoal on white). */\n.tw-aliyah{\n  --red:#c70c0f; --red-soft:#fbeaea; --ink:#1c1c1c; --muted:#5f5a58; --rule:#e6e1df; --paper:#ffffff; --tint:#f8f6f5;\n  --f-head:\"Poppins\", Arial, sans-serif; --f-body:\"Cantarell\", Arial, sans-serif;\n  color-scheme:light; background:var(--paper); color:var(--ink); font-family:var(--f-body); font-size:17px; line-height:1.65;\n  padding-left:max(16px, env(safe-area-inset-left, 0px)); padding-right:max(16px, env(safe-area-inset-right, 0px)); padding-block:28px 36px;\n}\n.tw-aliyah *{box-sizing:border-box}\n.tw-in{max-width:760px;margin:0 auto}\n.tw-top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}\n.tw-eyebrow{font-family:var(--f-head);font-weight:600;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--red);display:flex;align-items:center;gap:8px}\n.tw-eyebrow .dot{width:8px;height:8px;border-radius:50%;background:var(--red);box-shadow:0 0 0 4px var(--red-soft)}\n.tw-date{color:var(--muted);letter-spacing:.06em}\n.tw-lang{display:inline-flex;border:1px solid var(--rule);border-radius:999px;padding:3px}\n.tw-lang button{font:600 12px/1 var(--f-head);letter-spacing:.06em;border:0;background:transparent;color:var(--muted);padding:7px 12px;border-radius:999px;cursor:pointer}\n.tw-lang button[aria-pressed=\"true\"]{background:var(--ink);color:#fff}\n\n.tw-week{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px;margin:0 0 22px}\n.tw-day{font-family:var(--f-head);border:1px solid var(--rule);background:var(--paper);border-radius:8px;padding:8px 2px 7px;text-align:center;cursor:pointer;color:var(--ink);display:grid;gap:1px}\n.tw-day b{font-size:16px;font-weight:600;line-height:1.2}\n.tw-day small{font-size:10.5px;letter-spacing:.04em;color:var(--muted);text-transform:uppercase}\n.tw-day[aria-current=\"true\"]{background:var(--red);border-color:var(--red);color:#fff}\n.tw-day[aria-current=\"true\"] small{color:#fff}\n.tw-day:disabled{cursor:default;background:var(--tint);color:#b7b0ad;border-style:dashed}\n.tw-day:disabled small{color:#c3bcb9}\n.tw-day:focus-visible,.tw-lang button:focus-visible,.tw-links a:focus-visible{outline:2px solid var(--ink);outline-offset:2px}\n\n.tw-card{border-top:4px solid var(--red);background:var(--paper)}\n.tw-head{padding:22px 0 6px}\n.tw-ref{font-family:var(--f-head);font-weight:600;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:0 0 14px}\n.tw-ref span{color:var(--red)}\n.tw-bless{font-style:italic;color:var(--muted);margin:0 0 10px}\n.tw-hook{font-family:var(--f-head);font-weight:700;font-size:clamp(26px,5vw,38px);line-height:1.15;letter-spacing:-.01em;margin:0 0 18px;text-wrap:balance}\n.tw-sum{margin:0 0 26px;padding:16px 18px;background:var(--tint);border-radius:8px}\n.tw-qs{list-style:none;margin:0;padding:0;display:grid;gap:26px;counter-reset:q}\n.tw-q{display:grid;grid-template-columns:36px minmax(0,1fr);gap:0 14px}\n.tw-q::before{counter-increment:q;content:counter(q);font-family:var(--f-head);font-weight:700;font-size:15px;width:32px;height:32px;border-radius:50%;border:2px solid var(--red);color:var(--red);display:grid;place-items:center;margin-top:2px}\n.tw-q h3{font-family:var(--f-head);font-weight:600;font-size:18px;line-height:1.35;margin:0 0 6px;text-wrap:balance}\n.tw-q h3 .r{font-weight:500;color:var(--muted);font-size:14px;white-space:nowrap}\n.tw-q p{margin:0 0 8px}\n.tw-key{margin:6px 0 10px;padding-left:14px;border-left:3px solid var(--rule)}\n.tw-key p{font-style:italic;font-weight:700;margin:0 0 4px}\n.tw-act{background:var(--red-soft);border-radius:8px;padding:12px 14px}\n.tw-act strong{font-family:var(--f-head);font-weight:600;color:var(--red);font-size:13px;letter-spacing:.06em;text-transform:uppercase;display:block;margin-bottom:2px}\n.tw-act .h{font-weight:700;display:block}\n.tw-act p{margin:4px 0 0}\n.tw-deep{margin:30px 0 0;padding:18px 20px;border:1px solid var(--rule);border-left:4px solid var(--red);border-radius:8px}\n.tw-deep h3{font-family:var(--f-head);font-weight:600;font-size:13px;letter-spacing:.1em;text-transform:uppercase;color:var(--red);margin:0 0 6px}\n.tw-deep p{margin:0}\n.tw-close{margin:30px 0 0;padding:22px 20px;background:var(--ink);color:#fff;border-radius:10px}\n.tw-close small{font-family:var(--f-head);font-weight:600;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#ff9c9d;display:block;margin-bottom:6px}\n.tw-close p{font-family:var(--f-head);font-weight:600;font-size:20px;line-height:1.35;margin:0}\n.tw-close p+p{font-family:var(--f-body);font-weight:400;font-size:16px;margin-top:8px}\n.tw-links{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px;font-family:var(--f-head);font-size:14px}\n.tw-links a{text-decoration:none;font-weight:600;padding:10px 16px;border-radius:999px;border:1px solid var(--ink);color:var(--ink)}\n.tw-links a.p{background:var(--red);border-color:var(--red);color:#fff}\n.tw-empty{padding:28px 0;color:var(--muted)}\n@media (max-width:520px){\n  .tw-aliyah{font-size:16px}\n  .tw-day small{font-size:9.5px}\n  .tw-q{grid-template-columns:30px minmax(0,1fr);gap:0 10px}\n  .tw-q::before{width:28px;height:28px;font-size:13px}\n}\n.tw-perma{margin:22px 0 0;font-family:var(--f-head);font-size:13px}\n.tw-perma a{color:var(--muted)}\n"; document.head.appendChild(st);
  root.innerHTML="<section class=\"tw-aliyah\" id=\"tw-aliyah\" aria-label=\"Aliyah of the Day\">\n  <div class=\"tw-in\">\n    <div class=\"tw-top\">\n      <div class=\"tw-eyebrow\"><span class=\"dot\" aria-hidden=\"true\"></span><span id=\"tw-label\">Aliyah of the Day</span><span class=\"tw-date\" id=\"tw-date\"></span></div>\n      <div class=\"tw-lang\" role=\"group\" aria-label=\"Language\">\n        <button type=\"button\" id=\"tw-en\" aria-pressed=\"true\">English</button>\n        <button type=\"button\" id=\"tw-af\" aria-pressed=\"false\">Afrikaans</button>\n      </div>\n    </div>\n    <div class=\"tw-week\" id=\"tw-week\" role=\"group\" aria-label=\"This week's Aliyot\"></div>\n    <article class=\"tw-card\" id=\"tw-card\" aria-live=\"polite\"></article>\n    <div class=\"tw-links\">\n      <a class=\"p\" href=\"https://t.me/+VG6F0CBWsCKG2KgI\" target=\"_blank\" rel=\"noopener\" id=\"tw-tg\">Join us on Telegram</a>\n      <a href=\"https://chat.whatsapp.com/HZhD7k7usKQI3E9u4mhv1K\" target=\"_blank\" rel=\"noopener\" id=\"tw-wa\">Join the WhatsApp group</a>\n    </div>\n  </div>\n</section>\n";
  var BASE="https://thewaydhymin-eng.github.io/Aliyah";
  var ALIYOT=[{"date":"2026-11-01","parashah":"Chayey Sarah","year":"5787","aliyah":1,"ref":"Bereishit 23:1–16","en":{"title":"There Is Room to Weep","blessing":"Shavuah Tov! May today's Aliyah help me face grief honestly and accept help with what must be done.","hook":"Avraham wept for Sarah before he negotiated for her grave.","summary":"Sarah dies at 127 in Hebron, and Avraham comes to mourn and weep for her. He then asks the sons of Heth for a burial possession. He requests the cave of Machpelah at its full price and weighs out the 400 shekels named by Ephron (23:1–16).","questions":[{"q":"What does Avraham do before discussing the burial?","ref":"23:2–4","answer":"He mourns Sarah and weeps for her.","key":["The man who trusted יהוה still cried.","Nothing in this account treats his tears as a failure."],"action":"Allow yourself ten quiet minutes to acknowledge a loss without explaining it away.","detail":""},{"q":"What does Avraham ask for when graves are offered to him?","ref":"23:6–9, 13","answer":"He asks to purchase a particular cave at its full price.","key":["He makes the arrangement he wants clear.","The passage gives no market comparison, so I cannot claim that Ephron cheated him."],"action":"Put the price and terms of one pending agreement in writing.","detail":"Make your arrangements clear!"},{"q":"How do I read these tears alongside Yeshua’s demand to follow Him?","ref":"23:2; Luke 9:59–60","answer":"I must take Yeshua’s urgent call seriously without inventing a prohibition on mourning.","key":["Luke does not tell me whether the man’s father has already died.","I cannot use that silence to shame a bereaved person."],"action":"Read Luke 9:59–60 beside Bereishit 23:2 before commenting on someone’s grief.","detail":""},{"q":"When someone is grieving, do I make room for their pain or try to stop it?","ref":"23:2–3","answer":"I need to listen before deciding what they ought to feel.","key":["A quick instruction to be strong can leave someone carrying their loss alone.","Sitting with them may be the help they need today."],"action":"Contact one grieving person and offer to listen without giving advice.","detail":"Sit shiva (look it up and live it!)"},{"q":"What practical help can I offer someone who is grieving?","ref":"23:3–16","answer":"I can offer to carry one specific task, with their permission.","key":["Funeral arrangements, meals and paperwork arrive while people are still in shock.","A clear offer is easier to answer than a vague promise of help."],"action":"Offer one meal, lift or administrative task, and let the person choose.","detail":""}],"closing":"","actionOfDay":"Before tonight, offer a grieving person one specific task you can do this week; follow their wishes."},"af":{"title":"Daar Is Plek vir Trane","blessing":"Shavuah Tov! Mag vandag se Aliyah my help om eerlik te rou en hulp te aanvaar met wat gedoen moet word.","hook":"Avraham het oor Sarah gehuil voordat hy oor haar graf onderhandel het.","summary":"Sarah sterf op 127 in Gevron, en Avraham kom om oor haar te rou en haar te beween. Daarna vra hy die seuns van Get vir ’n graf as eiendom. Hy vra die grot van Magpela teen die volle prys en weeg die 400 shekels af wat Efron genoem het (23:1–16).","questions":[{"q":"Wat doen Avraham voordat hy die begrafnis bespreek?","ref":"23:2–4","answer":"Hy rou oor Sarah en huil oor haar.","key":["Die man wat יהוה vertrou het, het steeds gehuil.","Niks in hierdie gedeelte stel sy trane as ’n mislukking voor nie."],"action":"Gun jouself tien stil minute om ’n verlies te erken sonder om dit weg te praat.","detail":""},{"q":"Waarvoor vra Avraham toe hulle vir hom grafte aanbied?","ref":"23:6–9, 13","answer":"Hy vra om ’n bepaalde grot teen die volle prys te koop.","key":["Hy stel duidelik wat hy wil reël.","Die gedeelte vergelyk nie grondpryse nie; ek kan dus nie beweer dat Efron hom verkul het nie."],"action":"Skryf die prys en voorwaardes van een uitstaande ooreenkoms neer.","detail":""},{"q":"Hoe lees ek hierdie trane saam met Yeshua se oproep om Hom te volg?","ref":"23:2; Lukas 9:59–60","answer":"Ek moet Yeshua se dringende oproep ernstig opneem sonder om ’n verbod op rou daaruit af te lei.","key":["Lukas sê nie of die man se vader reeds dood was nie.","Ek kan nie daardie stilte gebruik om iemand wat rou, te beskaam nie."],"action":"Lees Lukas 9:59–60 saam met Bereishit 23:2 voordat jy oor iemand se rou kommentaar lewer.","detail":""},{"q":"Maak ek plek vir iemand se hartseer, of probeer ek dit laat ophou?","ref":"23:2–3","answer":"Ek moet luister voordat ek besluit hoe die persoon behoort te voel.","key":["Om gou te sê iemand moet sterk wees, kan hulle alleen laat voel met hulle verlies.","Miskien het hulle vandag net iemand nodig wat by hulle sal sit."],"action":"Kontak iemand wat rou en bied aan om sonder raad te luister.","detail":""},{"q":"Watter praktiese hulp kan ek iemand gee wat rou?","ref":"23:3–16","answer":"Ek kan aanbied om met hulle toestemming een bepaalde taak oor te neem.","key":["Begrafnisreëlings, etes en papierwerk wag nie totdat die skok verby is nie.","’n Duidelike aanbod is makliker om op te antwoord as ’n vae belofte van hulp."],"action":"Bied een ete, rit of administratiewe taak aan en laat die persoon kies.","detail":""}],"closing":"","actionOfDay":"Bied voor vanaand aan om hierdie week een bepaalde taak vir iemand wat rou te doen; respekteer hulle wense."}},{"date":"2026-11-02","parashah":"Chayey Sarah","year":"5787","aliyah":2,"ref":"Bereishit 23:17–24:9","en":{"title":"Can I Accept Their No?","blessing":"Boker Tov! May today's Aliyah help me carry my responsibilities without taking over someone else’s choice.","hook":"Avraham trusted יהוה with the journey and still made provision for the woman to refuse.","summary":"The field and cave become Avraham’s purchased possession, and he buries Sarah there. Later, he commissions his senior servant to find a wife for Yitzchak among his relatives. He forbids taking Yitzchak back to his former land and releases the servant from the oath if the woman will not come (23:17–24:9).","questions":[{"q":"What happens if the woman will not come?","ref":"24:5–8","answer":"The servant is released from the oath, but he must not take Yitzchak back.","key":["Avraham names a limit to the assignment.","The servant is not ordered to secure agreement at any cost.","Ensure a fair assignment!"],"action":"Write down what you are responsible for in one difficult situation and what another person must decide.","detail":""},{"q":"How does Avraham hold conviction and another person’s refusal together?","ref":"24:6–8","answer":"He maintains his instruction about the land while allowing for an unsuccessful proposal.","key":["He expects יהוה to guide the journey.","That expectation does not erase the possibility of refusal."],"action":"Identify one conviction you must keep without forcing someone else’s agreement.","detail":""},{"q":"What does Psalm 106 add to this concern about family influence?","ref":"24:3–8; Psalm 106:35–39","answer":"It shows how learning destructive practices can lead a community into grave wrongdoing.","key":["The psalm names idolatry and the shedding of innocent blood.","It does not give me permission to despise people because of their ancestry."],"action":"Name one harmful practice you need to refuse rather than labelling an entire group.","detail":""},{"q":"Have I used “יהוה told me” to make someone feel unable to refuse me?","ref":"24:7–8","answer":"I need to check whether my language has made room for an honest answer.","key":["This matters when discussing marriage, ministry, money or a move.","My certainty does not make another person’s decision mine to control."],"action":"Remove spiritual pressure from one request and ask for an honest answer.","detail":""},{"q":"What can I do when someone’s answer disappoints me?","ref":"24:8","answer":"I can respect their answer and decide how to proceed within my own responsibilities.","key":["Disappointment can be painful without justifying repeated pressure.","A willing answer cannot be produced by wearing someone down."],"action":"Accept one clear refusal without reopening the argument today.","detail":""}],"closing":"","actionOfDay":"Within 24 hours, revisit one request you have made and make clear that the other person may answer honestly, including no."},"af":{"title":"Kan Ek Hulle Nee Aanvaar?","blessing":"Boker Tov! Mag vandag se Aliyah my help om my verantwoordelikhede na te kom sonder om iemand anders se keuse oor te neem.","hook":"Avraham het יהוה met die reis vertrou en steeds voorsiening gemaak dat die vrou kon weier.","summary":"Die grond en grot word Avraham se gekoopte eiendom, en hy begrawe Sarah daar. Later stuur hy sy oudste dienaar om onder sy familie ’n vrou vir Yitzchak te gaan soek. Hy verbied dat Yitzchak na sy vorige land teruggeneem word en stel die dienaar vry van die eed indien die vrou nie wil kom nie (23:17–24:9).","questions":[{"q":"Wat gebeur as die vrou nie wil saamkom nie?","ref":"24:5–8","answer":"Die dienaar is vry van die eed, maar hy mag Yitzchak nie terugneem nie.","key":["Avraham stel ’n grens aan die opdrag.","Die dienaar hoef nie ten alle koste ’n ja te kry nie."],"action":"Skryf neer waarvoor jy in een moeilike situasie verantwoordelik is en wat iemand anders moet besluit.","detail":""},{"q":"Hoe hou Avraham sy oortuiging en iemand anders se moontlike weiering bymekaar?","ref":"24:6–8","answer":"Hy hou by sy opdrag oor die land en maak tog voorsiening dat die huweliksvoorstel nie aanvaar word nie.","key":["Hy verwag dat יהוה die reis sal lei.","Dit beteken nie dat die vrou se moontlike weiering verdwyn nie."],"action":"Benoem een oortuiging waarby jy moet bly sonder om iemand anders se instemming af te dwing.","detail":""},{"q":"Wat voeg Psalm 106 by hierdie saak van familie-invloed?","ref":"24:3–8; Psalm 106:35–39","answer":"Dit wys hoe die aanleer van vernietigende gebruike ’n gemeenskap tot ernstige verkeerde dade kan lei.","key":["Die psalm noem afgodery en die vergieting van onskuldige bloed.","Dit gee my nie toestemming om mense oor hulle afkoms te verag nie."],"action":"Benoem een skadelike gebruik wat jy moet afwys eerder as om ’n hele groep te veroordeel.","detail":""},{"q":"Het ek al “יהוה het vir my gesê” gebruik sodat iemand nie durf nee sê nie?","ref":"24:7–8","answer":"Ek moet ondersoek of my woorde ruimte vir ’n eerlike antwoord gelaat het.","key":["Dit maak saak wanneer ons oor trou, bediening, geld of verhuising praat.","My sekerheid gee my nie beheer oor iemand anders se besluit nie."],"action":"Haal die geestelike druk uit een versoek en vra vir ’n eerlike antwoord.","detail":""},{"q":"Wat kan ek doen wanneer iemand se antwoord my teleurstel?","ref":"24:8","answer":"Ek kan die antwoord respekteer en besluit hoe om my eie verantwoordelikhede verder na te kom.","key":["Teleurstelling kan seer wees sonder dat dit aanhoudende druk regverdig.","Om iemand moeg te praat, gee my nie ’n gewillige antwoord nie."],"action":"Aanvaar een duidelike weiering sonder om vandag weer daaroor te stry.","detail":""}],"closing":"","actionOfDay":"Gaan binne 24 uur terug na een versoek wat jy gerig het en maak dit duidelik dat die ander persoon eerlik mag antwoord, ook nee."}},{"date":"2026-11-03","parashah":"Chayey Sarah","year":"5787","aliyah":3,"ref":"Bereishit 24:10–26","en":{"title":"Notice Who Carries the Water","blessing":"Boker Tov! May today's Aliyah teach me to notice character in ordinary work and share the load at home.","hook":"Rivkah’s kindness meant repeated trips to the well until the camels had finished drinking.","summary":"The servant travels with ten camels and prays beside the well for a woman who will offer water to him and his camels. Rivkah arrives before he finishes speaking and does exactly that. He observes her, asks about her family and lodging, and bows in worship (24:10–26).","questions":[{"q":"What does Rivkah offer beyond the drink he requests?","ref":"24:17–20","answer":"She offers to draw water for his camels until they have finished drinking.","key":["She notices a need and follows through.","The account describes actual work, not merely a friendly greeting."],"action":"Finish one practical task that will ease someone else’s day.","detail":"Are you following through on a need you noticed?"},{"q":"Why does the servant continue watching and asking questions?","ref":"24:21–25","answer":"He is still seeking to know whether יהוה has made the journey successful.","key":["He does not stop observing after the first encouraging moment.","He also asks who she is and whether there is room to stay."],"action":"Ask one necessary factual question before making a major commitment.","detail":"Keep observing! Do not lean on your own understanding!"},{"q":"How does Psalm 106 connect praise with ordinary conduct?","ref":"24:18–26; Psalm 106:1–3","answer":"It praises יהוה and calls those who practise justice blessed.","key":["Rivkah’s helpfulness and the servant’s worship appear in the same scene.","Praise should lead me to examine how I treat people when work needs doing."],"action":"Share one household task before settling into your own plans.","detail":""},{"q":"Whose work have I stopped noticing because they always do it?","ref":"24:19–20","answer":"I need to look at who keeps carrying the repeated tasks around me.","key":["Meals, cleaning, lifts and care do not happen on their own.","Thanking someone matters; taking a turn matters too."],"action":"Ask the person carrying the routine work which task you can take over today.","detail":""},{"q":"How can I practise generosity without assuming one person must always serve?","ref":"24:18–20","answer":"I can offer help myself and agree on a fair share of the work.","key":["Rivkah’s voluntary offer does not entitle me to someone else’s exhaustion.","This passage first asks what I am willing to do."],"action":"Take responsibility for one agreed task from beginning to end.","detail":""}],"closing":"","actionOfDay":"Today, take over one routine task someone else usually carries and complete it without making them supervise you."},"af":{"title":"Sien Wie die Water Aandra","blessing":"Boker Tov! Mag vandag se Aliyah my leer om karakter in gewone werk raak te sien en tuis my deel te doen.","hook":"Rivkah se goedheid het beteken dat sy heen en weer na die put geloop het totdat die kamele klaar gedrink het.","summary":"Die dienaar reis met tien kamele en bid by die put vir ’n vrou wat vir hom en sy kamele water sal aanbied. Rivkah kom voordat hy klaar gepraat het en doen presies dit. Hy hou haar dop, vra oor haar familie en slaapplek, en buig in aanbidding neer (24:10–26).","questions":[{"q":"Wat bied Rivkah aan bo en behalwe die drinkwater wat hy vra?","ref":"24:17–20","answer":"Sy bied aan om vir sy kamele te skep totdat hulle genoeg gedrink het.","key":["Sy sien die behoefte raak en doen die werk klaar.","Die verhaal beskryf werklike inspanning, nie net ’n vriendelike groet nie."],"action":"Maak een praktiese taak klaar wat iemand anders se dag sal vergemaklik.","detail":""},{"q":"Waarom hou die dienaar aan om waar te neem en vrae te vra?","ref":"24:21–25","answer":"Hy probeer steeds vasstel of יהוה sy reis voorspoedig gemaak het.","key":["Hy hou nie ná die eerste bemoedigende oomblik op om op te let nie.","Hy vra ook wie sy is en of daar plek is om oor te bly."],"action":"Vra een nodige feitevraag voordat jy ’n groot verbintenis aangaan.","detail":""},{"q":"Hoe verbind Psalm 106 lof met ons gewone optrede?","ref":"24:18–26; Psalm 106:1–3","answer":"Dit loof יהוה en noem dié wat geregtigheid doen geseënd.","key":["Rivkah se hulpvaardigheid en die dienaar se aanbidding staan in dieselfde toneel.","Lof behoort my te laat kyk hoe ek mense behandel wanneer daar werk is."],"action":"Doen jou deel van ’n huistaak voordat jy met jou eie planne aangaan.","detail":""},{"q":"Wie se werk sien ek nie meer raak nie omdat hulle dit altyd doen?","ref":"24:19–20","answer":"Ek moet kyk wie om my die herhalende take bly dra.","key":["Etes, skoonmaak, vervoer en versorging gebeur nie vanself nie.","Dankie sê maak saak; om jou beurt te neem ook."],"action":"Vra die persoon wat die daaglikse werk dra watter taak jy vandag kan oorneem.","detail":""},{"q":"Hoe kan ek vrygewig wees sonder om te aanvaar dat een persoon altyd moet dien?","ref":"24:18–20","answer":"Ek kan self hulp aanbied en saam besluit hoe om die werk billik te verdeel.","key":["Rivkah se vrywillige aanbod gee my nie aanspraak op iemand anders se uitputting nie.","Hierdie gedeelte vra eers wat ek bereid is om te doen."],"action":"Neem een afgespreekte taak van begin tot einde op jou.","detail":""}],"closing":"","actionOfDay":"Neem vandag een roetinetaak oor wat iemand anders gewoonlik doen en handel dit af sonder dat hulle jou deur elke stap hoef te lei."}},{"date":"2026-11-04","parashah":"Chayey Sarah","year":"5787","aliyah":4,"ref":"Bereishit 24:27–52","en":{"title":"Say What You Came to Say","blessing":"Boker Tov! May today's Aliyah help me speak truthfully and finish the responsibility entrusted to me.","hook":"Avraham’s servant asked for a clear answer after explaining why he had come.","summary":"The servant blesses יהוה for His loyalty and guidance. At Rivkah’s home, he insists on explaining his business before eating and recounts his commission, prayer and encounter at the well. He asks the family for a definite answer; when Lavan and Bethuel agree, he bows to יהוה (24:27–52).","questions":[{"q":"What does the servant insist on doing before eating?","ref":"24:33–34","answer":"He insists on explaining the business that brought him there.","key":["He enjoys hospitality without forgetting his assignment.","He identifies whose servant he is and why he has come."],"action":"State the purpose of one necessary conversation in its opening sentence.","detail":""},{"q":"Does the servant hide the possibility that the proposal may be refused?","ref":"24:39–41, 49","answer":"No; he recounts the release from his oath and asks them to tell him if they will not agree.","key":["He presents his case and asks for a decision.","A clear answer will let him know what to do next."],"action":"Give one person the relevant facts they need to answer your request.","detail":"Learn from this passage how to represent the Master well."},{"q":"Why did Natan and Bath-sheba need to speak to Dawid?","ref":"1 Kings 1:11–27; 24:33","answer":"Adonijah had assumed the kingship, and Dawid needed to hear what was happening.","key":["Their report concerns a real threat to Bath-sheba and Shelomoh.","It shows why a difficult conversation may be an urgent responsibility."],"action":"Arrange one conversation about a concrete problem you have left unaddressed.","detail":""},{"q":"Am I avoiding a clear answer because I dislike disappointing someone?","ref":"24:49","answer":"I need to check whether my uncertainty is genuine or whether I am postponing an honest response.","key":["Sometimes I need more information, and I can say so.","Leaving someone waiting without explanation may keep them from making their next decision."],"action":"Send one honest answer or name the specific information and time you still need.","detail":""},{"q":"How can I seek clarity without becoming demanding?","ref":"24:49–52","answer":"I can ask plainly and leave room for an answer I do not prefer.","key":["The servant’s words include both agreement and refusal.","My request for clarity should be equally honest about those possibilities."],"action":"Ask for a decision respectfully and agree on a reasonable time to respond.","detail":""}],"closing":"","actionOfDay":"Before the day ends, answer one outstanding request honestly or give a clear date for your answer."},"af":{"title":"Sê Waarvoor Jy Gekom Het","blessing":"Boker Tov! Mag vandag se Aliyah my help om eerlik te praat en die verantwoordelikheid wat aan my toevertrou is, af te handel.","hook":"Avraham se dienaar het vir ’n duidelike antwoord gevra nadat hy verduidelik het waarom hy gekom het.","summary":"Die dienaar loof יהוה vir sy trou en leiding. By Rivkah se huis dring hy daarop aan om sy saak te stel voordat hy eet en vertel hy van sy opdrag, gebed en ontmoeting by die put. Hy vra die familie vir ’n besliste antwoord; toe Lavan en Betuél instem, buig hy voor יהוה neer (24:27–52).","questions":[{"q":"Wat wil die dienaar doen voordat hy eet?","ref":"24:33–34","answer":"Hy wil eers verduidelik watter saak hom daarheen gebring het.","key":["Hy ontvang gasvryheid sonder om sy opdrag te vergeet.","Hy sê wie se dienaar hy is en waarom hy gekom het."],"action":"Sê in die eerste sin van een nodige gesprek waaroor jy wil praat.","detail":""},{"q":"Steek die dienaar weg dat die voorstel geweier kan word?","ref":"24:39–41, 49","answer":"Nee; hy vertel dat hy van die eed vrygestel kan word en vra hulle om te sê as hulle nie instem nie.","key":["Hy stel sy saak en vra vir ’n besluit.","’n Duidelike antwoord sal hom help om te weet wat om volgende te doen."],"action":"Gee iemand die tersaaklike feite wat nodig is om jou versoek te beantwoord.","detail":""},{"q":"Waarom moes Natan en Batsheva met Dawid praat?","ref":"1 Konings 1:11–27; 24:33","answer":"AdoniYah het die koningskap oorgeneem, en Dawid moes hoor wat aangaan.","key":["Hulle verslag gaan oor ’n werklike bedreiging vir Batsheva en Shelomoh.","Dit wys waarom ’n moeilike gesprek ’n dringende verantwoordelikheid kan wees."],"action":"Reël een gesprek oor ’n werklike probleem wat jy tot nou toe vermy het.","detail":""},{"q":"Vermy ek ’n duidelike antwoord omdat ek iemand nie wil teleurstel nie?","ref":"24:49","answer":"Ek moet ondersoek of ek werklik onseker is en of ek ’n eerlike antwoord uitstel.","key":["Soms het ek meer inligting nodig, en ek kan dit sê.","As ek iemand sonder verduideliking laat wag, kan dit hulle eie besluite ophou."],"action":"Stuur een eerlike antwoord of sê presies watter inligting en tyd jy nog nodig het.","detail":""},{"q":"Hoe kan ek duidelikheid vra sonder om veeleisend te raak?","ref":"24:49–52","answer":"Ek kan reguit vra en ruimte laat vir ’n antwoord waarvan ek nie hou nie.","key":["Die dienaar maak plek vir instemming én weiering.","Ek moet net so eerlik wees wanneer ek duidelikheid vra."],"action":"Vra respekvol vir ’n besluit en kom ooreen op ’n redelike tyd om te antwoord.","detail":""}],"closing":"","actionOfDay":"Beantwoord voor die einde van die dag een uitstaande versoek eerlik, of gee ’n duidelike datum waarop jy sal antwoord."}},{"date":"2026-11-05","parashah":"Chayey Sarah","year":"5787","aliyah":5,"ref":"Bereishit 24:53–67","en":{"title":"Ask Her and Hear Her","blessing":"Boker Tov! May today's Aliyah help me respect another person’s voice and take my own commitments seriously.","hook":"Rivkah’s family had agreed, but they still called her and asked whether she would go.","summary":"The servant gives gifts, shares a meal and asks to leave the next morning. Rivkah’s brother and mother request a delay, then call her to ask whether she will go; she agrees and departs with her attendants. She meets Yitzchak, becomes his wife, and he loves her and finds comfort after his mother’s death (24:53–67).","questions":[{"q":"Who is asked when the departure becomes a point of disagreement?","ref":"24:55–58","answer":"Rivkah herself is called and asked whether she will go with the man.","key":["The family has already agreed to the match.","The account nevertheless records her own answer about going."],"action":"Ask the person most affected by a decision what they actually want.","detail":""},{"q":"What can I responsibly say about the family’s proposed delay?","ref":"24:55–58","answer":"They ask for more time, but the passage does not state their motive.","key":["Missing someone, needing preparation and trying to control someone are different things.","I cannot decide which is happening here from an unstated motive."],"action":"Separate an observable concern from what you are assuming about someone’s intentions.","detail":""},{"q":"Where does this departure meet Yeshua’s words about following?","ref":"24:58–61; Luke 9:61–62","answer":"Both passages put a stated willingness alongside the need to set out.","key":["Rivkah actually leaves, and Yeshua speaks of sustained commitment.","That connection does not make every request to hurry a command from יהוה."],"action":"Name one commitment you have freely made and its next practical step.","detail":""},{"q":"When someone I love is ready to leave, do I listen or make them carry my fear?","ref":"24:57–60","answer":"I need to express my concern without making them responsible for keeping me comfortable.","key":["A departure can hurt even when I support it.","I can ask for contact and offer a blessing without using guilt."],"action":"Express one concern directly without adding a threat or guilt-laden remark.","detail":""},{"q":"What does loving a grieving spouse require of me?","ref":"24:67","answer":"I can offer affection and patience without expecting to replace the person they lost.","key":["The verse says Yitzchak loved Rivkah and was comforted.","It does not make a new spouse responsible for removing every trace of grief."],"action":"Ask your spouse or someone close to you what kind of support would help today.","detail":""}],"closing":"","actionOfDay":"Within 24 hours, ask someone affected by a shared decision for their own view and listen without interrupting or correcting it."},"af":{"title":"Vra Haar en Luister","blessing":"Boker Tov! Mag vandag se Aliyah my help om iemand anders se stem te respekteer en my eie verbintenisse ernstig op te neem.","hook":"Rivkah se familie het ingestem, maar hulle het haar steeds geroep en gevra of sy wou gaan.","summary":"Die dienaar gee geskenke, eet saam met die familie en vra om die volgende oggend te vertrek. Rivkah se broer en moeder vra vir uitstel en roep haar toe om te vra of sy wil gaan; sy stem in en vertrek saam met haar gevolg. Sy ontmoet Yitzchak, word sy vrou, en hy het haar lief en vind troos ná sy moeder se dood (24:53–67).","questions":[{"q":"Wie word gevra toe daar oor die vertrek verskil word?","ref":"24:55–58","answer":"Rivkah word self geroep en gevra of sy met die man wil saamgaan.","key":["Die familie het reeds tot die huwelik ingestem.","Tog teken die verhaal haar eie antwoord oor die vertrek aan."],"action":"Vra die persoon wat die meeste deur ’n besluit geraak word wat hulle self wil hê.","detail":""},{"q":"Wat kan ek met sekerheid oor die familie se versoek om uitstel sê?","ref":"24:55–58","answer":"Hulle vra vir meer tyd, maar die gedeelte sê nie waarom nie.","key":["Om iemand te mis, voorbereiding nodig te hê en iemand te probeer beheer, is verskillende dinge.","Ek kan nie op grond van ’n ongenoemde motief besluit wat hier gebeur nie."],"action":"Onderskei ’n werklike besorgdheid van jou aannames oor iemand se bedoelings.","detail":""},{"q":"Waar sluit hierdie vertrek by Yeshua se woorde oor navolging aan?","ref":"24:58–61; Lukas 9:61–62","answer":"In albei gedeeltes staan uitgesproke gewilligheid langs die noodsaak om te vertrek.","key":["Rivkah gaan werklik, en Yeshua praat van volgehoue toewyding.","Dit maak nie elke versoek om haastig te wees ’n opdrag van יהוה nie."],"action":"Benoem een verbintenis wat jy vrywillig aangegaan het en die volgende praktiese stap.","detail":""},{"q":"Luister ek wanneer iemand vir wie ek lief is gereed is om te gaan, of laat ek hulle my vrees dra?","ref":"24:57–60","answer":"Ek moet my besorgdheid uitspreek sonder om hulle verantwoordelik te maak om my gerus te hou.","key":["’n Afskeid kan seer wees al ondersteun ek die besluit.","Ek kan vir kontak vra en ’n seën uitspreek sonder om skuldgevoelens te gebruik."],"action":"Spreek een bekommernis reguit uit sonder ’n dreigement of verwyt.","detail":""},{"q":"Wat vra dit van my om ’n huweliksmaat wat rou lief te hê?","ref":"24:67","answer":"Ek kan liefde en geduld bied sonder om die persoon wat hulle verloor het te probeer vervang.","key":["Die vers sê Yitzchak het Rivkah liefgehad en is getroos.","Dit maak ’n nuwe huweliksmaat nie verantwoordelik om alle hartseer te laat verdwyn nie."],"action":"Vra jou huweliksmaat of iemand na aan jou watter ondersteuning vandag sal help.","detail":""}],"closing":"","actionOfDay":"Vra binne 24 uur iemand wat deur ’n gesamentlike besluit geraak word vir hulle eie mening en luister sonder om hulle te onderbreek of reg te help."}},{"date":"2026-11-06","parashah":"Chayey Sarah","year":"5787","aliyah":6,"ref":"Bereishit 25:1–11","en":{"title":"Settle What You Can Today","blessing":"Boker Tov! May today's Aliyah give me the courage to discuss the responsibilities my family will one day inherit.","hook":"Avraham made arrangements for his sons while he was still alive.","summary":"Avraham has further sons through Keturah. He gives his possessions to Yitzchak and gives gifts to the sons of his concubines, sending them east while he is still alive. He dies at 175; Yitzchak and Yishmael bury him beside Sarah, and Elohim blesses Yitzchak after his father’s death (25:1–11).","questions":[{"q":"When does Avraham make the arrangements described for his sons?","ref":"25:5–6","answer":"He makes them while he is still alive.","key":["The text names both Yitzchak’s inheritance and gifts to the other sons.","These arrangements are made before the burial scene."],"action":"List the family arrangements that currently depend on your unspoken intentions.","detail":""},{"q":"Does this passage give every parent a rule to leave everything to one child?","ref":"25:5–6","answer":"No; it describes Avraham’s particular arrangements rather than issuing a general inheritance command.","key":["I must not use this account to justify a preference I already have.","My own responsibilities require careful attention to the people affected."],"action":"Write down who would be affected by an arrangement you are considering.","detail":""},{"q":"What does Dawid’s situation add to this reading?","ref":"25:5–6; 1 Kings 1:18–21, 29–30","answer":"It shows the danger of an unsettled succession and Dawid’s decision to act on his oath that day.","key":["Bath-sheba names a threat to herself and Shelomoh.","A private intention had not prevented a public crisis."],"action":"Tell the appropriate person where your important instructions are kept.","detail":""},{"q":"What am I avoiding because I dislike talking about death?","ref":"25:6–8","answer":"I need to identify what my silence would leave someone else to sort out.","key":["This may include dependants, debts, documents or care arrangements.","I do not have to solve everything today to begin an honest conversation."],"action":"Choose one unfinished responsibility and name the person who needs to discuss it with you.","detail":""},{"q":"What can I say about Yitzchak and Yishmael burying their father together?","ref":"25:9–10","answer":"They both take part in the burial, but the passage does not describe a complete reconciliation.","key":["I can honour that shared act without inventing the brothers’ feelings.","In my own family, one limited act of cooperation may be possible even when other matters remain unresolved."],"action":"Propose one practical shared task if contact is safe and appropriate.","detail":""}],"closing":"","actionOfDay":"Within 24 hours, list three unfinished family responsibilities and arrange one conversation to begin addressing the first."},"af":{"title":"Reël Vandag Wat Jy Kan","blessing":"Boker Tov! Mag vandag se Aliyah my moed gee om te praat oor die verantwoordelikhede wat my familie eendag sal oorneem.","hook":"Avraham het reëlings vir sy seuns getref terwyl hy nog geleef het.","summary":"Avraham het nog seuns by Ketura. Hy gee sy besittings aan Yitzchak en gee geskenke aan die seuns van sy byvroue; hy laat hulle ooswaarts wegtrek terwyl hy nog leef. Hy sterf op 175; Yitzchak en Yishmael begrawe hom langs Sarah, en Elohim seën Yitzchak ná sy vader se dood (25:1–11).","questions":[{"q":"Wanneer tref Avraham die genoemde reëlings vir sy seuns?","ref":"25:5–6","answer":"Hy tref dit terwyl hy nog leef.","key":["Die teks noem Yitzchak se erfenis én geskenke aan die ander seuns.","Hierdie reëlings word voor die begrafnistoneel getref."],"action":"Maak ’n lys van die familiereëlings wat tans net op jou onuitgesproke voornemens berus.","detail":""},{"q":"Gee hierdie gedeelte elke ouer ’n reël om alles aan een kind na te laat?","ref":"25:5–6","answer":"Nee; dit beskryf Avraham se bepaalde reëlings en gee nie ’n algemene erfbevel nie.","key":["Ek moet nie hierdie verhaal gebruik om ’n bestaande voorkeur te regverdig nie.","My eie verantwoordelikhede vra dat ek die mense wat geraak word deeglik in ag neem."],"action":"Skryf neer wie deur ’n reëling wat jy oorweeg geraak sal word.","detail":""},{"q":"Wat voeg Dawid se situasie by hierdie lesing?","ref":"25:5–6; 1 Konings 1:18–21, 29–30","answer":"Dit wys die gevaar van ’n onbesliste opvolging en Dawid se besluit om sy eed daardie dag uit te voer.","key":["Batsheva noem die bedreiging vir haarself en Shelomoh.","’n Voorneme wat nie behoorlik uitgevoer is nie, het nie ’n openbare krisis gekeer nie."],"action":"Vertel die regte persoon waar jou belangrike instruksies gebêre word.","detail":""},{"q":"Wat vermy ek omdat ek nie oor die dood wil praat nie?","ref":"25:6–8","answer":"Ek moet vasstel wat my stilte iemand anders sal laat uitsorteer.","key":["Dit kan afhanklikes, skuld, dokumente of versorgingsreëlings insluit.","Ek hoef nie vandag alles op te los om ’n eerlike gesprek te begin nie."],"action":"Kies een onafgehandelde verantwoordelikheid en benoem die persoon met wie jy daaroor moet praat.","detail":""},{"q":"Wat kan ek sê oor Yitzchak en Yishmael wat hulle vader saam begrawe?","ref":"25:9–10","answer":"Hulle neem albei aan die begrafnis deel, maar die gedeelte beskryf nie ’n volledige versoening nie.","key":["Ek kan daardie gesamentlike daad erken sonder om die broers se gevoelens uit te dink.","In my eie familie kan een beperkte daad van samewerking moontlik wees al bly ander sake onopgelos."],"action":"Stel een praktiese taak voor wat julle kan deel indien kontak veilig en gepas is.","detail":""}],"closing":"","actionOfDay":"Maak binne 24 uur ’n lys van drie onafgehandelde familieverantwoordelikhede en reël een gesprek om die eerste te begin aanpak."}},{"date":"2026-11-07","parashah":"Chayey Sarah","year":"5787","aliyah":7,"ref":"Bereishit 25:12–18","en":{"title":"Do I Only Remember the Conflict?","blessing":"Shabbat Shalom! May today's Aliyah help me speak about other families with the care I want shown to my own.","hook":"The Torah records Yishmael’s sons by name and gives an account of his life and death.","summary":"The genealogy identifies Yishmael as Avraham’s son, born to Hagar. It names his twelve sons and describes twelve princes according to their clans and settlements. Yishmael dies at 137, and the account records where his descendants live (25:12–18).","questions":[{"q":"What does the Torah record about Yishmael’s family?","ref":"25:12–16","answer":"It gives the names of his twelve sons and identifies their clans and settlements.","key":["These people receive a place in the account.","I should pay attention to what is recorded before reducing them to a label."],"action":"Read the twelve names aloud without skipping the genealogy.","detail":""},{"q":"Does Yitzchak’s place in the preceding account make Yishmael’s life disappear?","ref":"25:11–18","answer":"No; the Torah follows the blessing of Yitzchak with Yishmael’s genealogy.","key":["The two accounts have distinct content.","Paying attention to one does not require me to erase the other."],"action":"Describe someone outside your own circle without beginning with your disagreement.","detail":""},{"q":"How does this genealogy connect to יהוה’s earlier words about Yishmael?","ref":"25:16; Bereishit 17:20","answer":"The twelve princes correspond to the earlier promise that Yishmael would father twelve princes.","key":["This is a specific textual connection.","I do not need to assign these names to present-day nations to recognise it."],"action":"Read Bereishit 17:20 beside 25:16 and identify the shared detail.","detail":""},{"q":"Have I made someone’s family history the whole explanation of who they are?","ref":"25:12–17","answer":"I need to ask what I actually know about the person in front of me.","key":["A surname, nationality or painful family association can shape my assumptions.","It cannot tell me everything about an individual’s conduct."],"action":"Replace one generalisation with a question you can ask respectfully.","detail":""},{"q":"How should this affect the way I speak this Shabbat?","ref":"25:13–17","answer":"I can speak accurately about a person and refuse insults about their whole family or people.","key":["Specific wrongdoing can be named without extending blame to everyone related to the offender.","Careful speech still leaves room for necessary boundaries."],"action":"Correct one sweeping statement before you repeat or forward it.","detail":""}],"closing":"","actionOfDay":"Before sharing a claim about a family or people, identify its evidence and remove any blame that goes beyond the specific conduct described.","deeper":"The Haftarah, 1 Kings 1:1–31, opens where this Parashah turns: Dawid is old and advanced in days (1 Kings 1:1), as Avraham is (Bereishit 24:1). Avraham secures a wife for Yitzchak and settles his inheritance while he is still alive (24:3–4; 25:5–6); Dawid’s succession is left unsettled until Natan and Bath-sheba speak to him, and then he acts on his oath that same day (1 Kings 1:11–30). In both accounts the line of the promise is protected by a father who takes responsibility before his death. Mattityahu opens the Brit Chadashah by naming Yeshua the Messiah as son of Dawid, son of Avraham (Mattityahu 1:1): the very line both men guarded."},"af":{"title":"Onthou Ek Net die Konflik?","blessing":"Shabbat Shalom! Mag vandag se Aliyah my help om oor ander families te praat met die sorg wat ek vir my eie familie verlang.","hook":"Die Torah noem Yishmael se seuns by die naam en vertel van sy lewe en dood.","summary":"Die geslagsregister identifiseer Yishmael as Avraham se seun wat uit Hagar gebore is. Dit noem sy twaalf seuns en beskryf twaalf heersers volgens hulle stamme en woonplekke. Yishmael sterf op 137, en die verhaal teken aan waar sy nageslag woon (25:12–18).","questions":[{"q":"Wat teken die Torah oor Yishmael se familie aan?","ref":"25:12–16","answer":"Dit gee die name van sy twaalf seuns en noem hulle stamme en woonplekke.","key":["Hierdie mense kry plek in die verhaal.","Ek behoort op te let wat geskryf staan voordat ek hulle tot ’n etiket reduseer."],"action":"Lees die twaalf name hardop sonder om die geslagsregister oor te slaan.","detail":""},{"q":"Laat Yitzchak se plek in die voorafgaande verhaal Yishmael se lewe verdwyn?","ref":"25:11–18","answer":"Nee; ná die seën van Yitzchak volg Yishmael se geslagsregister.","key":["Die twee verhale het elkeen hulle eie inhoud.","Om die een ernstig op te neem, vereis nie dat ek die ander uitwis nie."],"action":"Beskryf iemand buite jou eie kring sonder om met julle verskil te begin.","detail":""},{"q":"Hoe sluit hierdie geslagsregister by יהוה se vroeëre woorde oor Yishmael aan?","ref":"25:16; Bereishit 17:20","answer":"Die twaalf heersers stem ooreen met die vroeëre belofte dat Yishmael twaalf heersers sou verwek.","key":["Dit is ’n bepaalde teksverband.","Ek hoef nie hierdie name aan hedendaagse volke toe te skryf om dit raak te sien nie."],"action":"Lees Bereishit 17:20 saam met 25:16 en wys die ooreenstemmende besonderheid uit.","detail":""},{"q":"Het ek iemand se familiegeskiedenis die hele verklaring gemaak van wie hulle is?","ref":"25:12–17","answer":"Ek moet vra wat ek werklik weet van die persoon voor my.","key":["’n Van, nasionaliteit of pynlike familieverband kan my aannames beïnvloed.","Dit vertel my nie alles van ’n individu se optrede nie."],"action":"Vervang een veralgemening met ’n vraag wat jy respekvol kan vra.","detail":""},{"q":"Hoe behoort dit my woorde hierdie Shabbat te beïnvloed?","ref":"25:13–17","answer":"Ek kan akkuraat oor iemand praat en weier om hulle hele familie of volk te beledig.","key":["Bepaalde verkeerde dade kan benoem word sonder om almal wat aan die oortreder verwant is te blameer.","Noukeurige woorde laat steeds plek vir nodige grense."],"action":"Stel een veralgemening reg voordat jy dit herhaal of aanstuur.","detail":""}],"closing":"","actionOfDay":"Voordat jy ’n bewering oor ’n familie of volk deel, bepaal waarop dit berus en verwyder enige blaam wat verder as die genoemde optrede strek.","deeper":"Die Haftarah, 1 Konings 1:1–31, begin waar hierdie Parashah draai: Dawid is oud en hoog bejaard (1 Konings 1:1), net soos Avraham (Bereishit 24:1). Avraham reël ’n vrou vir Yitzchak en handel sy erfenis af terwyl hy nog leef (24:3–4; 25:5–6); Dawid se opvolging bly onbeslis totdat Natan en Batsheva met hom praat, en dan voer hy sy eed nog dieselfde dag uit (1 Konings 1:11–30). In albei verhale word die lyn van die belofte beskerm deur ’n vader wat voor sy dood verantwoordelikheid neem. Mattityahu begin die Brit Chadashah deur Yeshua die Messias die seun van Dawid, die seun van Avraham te noem (Mattityahu 1:1): presies die lyn wat albei manne bewaak het."}},{"date":"2026-11-08","parashah":"Toldot","year":"5787","aliyah":1,"ref":"Bereishit 25:19–26:5","en":{"title":"What Hunger Sells","blessing":"Shavuah Tov! May this week’s first Aliyah teach us to value what יהוה has given above what our hunger demands.","hook":"Esav sold his birthright for one meal and walked away satisfied.","summary":"Yitzchak pleads with יהוה for Rivkah because she is barren, and she conceives twins who struggle within her. יהוה tells her that two nations are in her womb and that the older will serve the younger; Esav is born first, and Yaakov follows holding his heel. Years later Esav comes in exhausted from the field and sells his birthright to Yaakov under oath for bread and lentil stew, and the text says he despised it. When famine comes, יהוה tells Yitzchak not to go down to Egypt but to stay in the land, and confirms to him the oath He swore to Avraham, because Avraham obeyed His voice.","questions":[{"q":"What did Esav do with his birthright?","ref":"25:29–34","answer":"He sold it to Yaakov under oath for bread and lentil stew, then ate, drank, rose and went his way.","key":["The text gives its own verdict: Esav despised his birthright.","When the meal was finished, he showed no sense of loss."],"action":"Name what you are trading for immediate relief.","detail":"Write down one thing of lasting value you have been neglecting because something else feels more urgent today. Next to it, write what that urgency is really offering you."},{"q":"Why does Yitzchak receive the promise “because Avraham obeyed”?","ref":"26:2–5","answer":"יהוה confirms His oath to Yitzchak and gives the reason: Avraham obeyed His voice and kept His charge, His commandments, His statutes and His Torot.","key":["Long before Sinai, the text already speaks of commandments, statutes and Torot.","One generation’s obedience shapes the blessing spoken over the next."],"action":"Let someone after you see one commandment you keep.","detail":"Choose one command you keep faithfully, such as Shabbat, honest dealing or giving. Explain to a child, grandchild or younger believer why you keep it."},{"q":"How does the Brit Chadashah use Esav as a warning?","ref":"25:34; Hebrews 12:16–17","answer":"The writer of Hebrews warns believers not to be like Esav, who sold his birthright for a single meal and later could not undo it, though he sought the blessing with tears.","key":["Bereishit records the sale. Hebrews records the cost.","A moment of appetite can have consequences that tears cannot reverse."],"action":"Read Hebrews 12:14–17 beside Bereishit 25:29–34.","detail":"Mark what the writer of Hebrews calls Esav. Then ask where the same attitude has room in your own life."},{"q":"What am I treating as worthless because it does not feed me today?","ref":"25:32","answer":"Esav reasoned that he was about to die, so what use was a birthright to him.","key":["He measured an inheritance by the needs of one afternoon.","I can call something set apart “useless” simply because its value lies in the future."],"action":"Restore one inheritance you have been treating as optional.","detail":"It may be your Shabbat, your time in the Word, your family’s instruction in the Torah or your covenant faithfulness. Put it back in your diary this week, at a fixed time."},{"q":"Will I stay where יהוה placed me when hunger pushes me toward Egypt?","ref":"26:1–3","answer":"During the famine, יהוה told Yitzchak not to go down to Egypt but to stay in the land He would show him, and promised to be with him.","key":["Hunger appears twice in this Aliyah: Esav’s and the land’s.","Esav let his hunger decide. Yitzchak was told to let יהוה decide."],"action":"Stay faithful in one place where pressure is pushing you to leave obedience.","detail":"Name the “Egypt” that looks like the easy answer right now: a shortcut at work, a compromise in a relationship or a quick fix with money. Decide today that you will not go down there."}],"closing":"Hunger passes. A birthright does not come back.","actionOfDay":"Before tonight, identify one decision you are about to make out of pressure or appetite. Delay it by 24 hours and bring it before יהוה in prayer before you act.","waSummary":"Esav comes in exhausted and sells his birthright to Yaakov for bread and lentil stew, and the text says he despised it."},"af":{"title":"Wat Honger Verkoop","blessing":"Shavuah Tov! Mag hierdie week se eerste Aliyah ons leer om wat יהוה gegee het, hoër te ag as wat ons honger eis.","hook":"Esav het sy eersgeboortereg vir een maaltyd verkoop en tevrede weggestap.","summary":"Yitzchak pleit by יהוה vir Rivkah omdat sy onvrugbaar is, en sy word swanger met ’n tweeling wat in haar met mekaar worstel. יהוה sê vir haar dat twee nasies in haar skoot is en dat die oudste die jongste sal dien; Esav word eerste gebore, en Yaakov volg met sy hand aan Esav se hakskeen. Jare later kom Esav uitgeput van die veld af en verkoop sy eersgeboortereg onder eed aan Yaakov vir brood en lensiesop, en die teks sê dat hy dit verag het. Wanneer hongersnood kom, sê יהוה vir Yitzchak om nie na Egipte af te trek nie maar in die land te bly, en bevestig aan hom die eed wat Hy aan Avraham gesweer het, omdat Avraham na sy stem geluister het.","questions":[{"q":"Wat het Esav met sy eersgeboortereg gedoen?","ref":"25:29–34","answer":"Hy het dit onder eed aan Yaakov verkoop vir brood en lensiesop, en toe geëet, gedrink, opgestaan en weggegaan.","key":["Die teks lewer self die oordeel: Esav het sy eersgeboortereg verag.","Toe die ete verby was, het hy geen verlies gevoel nie."],"action":"Noem wat jy verruil vir onmiddellike verligting.","detail":"Skryf een ding van blywende waarde neer wat jy afskeep omdat iets anders vandag dringender voel. Skryf langsaan wat daardie dringendheid jou eintlik aanbied."},{"q":"Hoekom ontvang Yitzchak die belofte “omdat Avraham geluister het”?","ref":"26:2–5","answer":"יהוה bevestig sy eed aan Yitzchak en gee die rede: Avraham het na sy stem geluister en sy opdrag, sy gebooie, sy insettinge en sy Torot gehou.","key":["Lank voor Sinai praat die teks reeds van gebooie, insettinge en Torot.","Een geslag se gehoorsaamheid vorm die seën wat oor die volgende uitgespreek word."],"action":"Laat iemand ná jou sien hoe jy een gebod hou.","detail":"Kies een gebod wat jy getrou hou, soos Shabbat, eerlike handel of gee. Verduidelik aan ’n kind, kleinkind of jonger gelowige hoekom jy dit hou."},{"q":"Hoe gebruik die Brit Chadashah vir Esav as waarskuwing?","ref":"25:34; Hebreërs 12:16–17","answer":"Die skrywer van Hebreërs waarsku gelowiges om nie soos Esav te wees nie, wat sy eersgeboortereg vir een maaltyd verkoop het en dit later nie kon ongedaan maak nie, al het hy die seën met trane gesoek.","key":["Bereishit teken die verkoop aan. Hebreërs teken die prys aan.","Een oomblik se aptyt kan gevolge hê wat trane nie kan omkeer nie."],"action":"Lees Hebreërs 12:14–17 saam met Bereishit 25:29–34.","detail":"Merk wat die skrywer van Hebreërs vir Esav noem. Vra dan waar dieselfde houding ruimte in jou eie lewe het."},{"q":"Wat behandel ek as waardeloos omdat dit my nie vandag voed nie?","ref":"25:32","answer":"Esav het geredeneer dat hy op die punt was om te sterf, so wat help ’n eersgeboortereg hom.","key":["Hy het ’n erfenis gemeet aan die behoeftes van een middag.","Ek kan iets wat afgesonder is “nutteloos” noem bloot omdat die waarde daarvan in die toekoms lê."],"action":"Herstel een erfenis wat jy as opsioneel behandel het.","detail":"Dit kan jou Shabbat wees, jou tyd in die Woord, jou gesin se onderrig in die Torah of jou verbondstrou. Sit dit hierdie week terug in jou dagboek, op ’n vaste tyd."},{"q":"Sal ek bly waar יהוה my geplaas het wanneer honger my na Egipte toe stoot?","ref":"26:1–3","answer":"Tydens die hongersnood het יהוה vir Yitzchak gesê om nie na Egipte af te trek nie maar in die land te bly wat Hy hom sou wys, en belowe om by hom te wees.","key":["Honger kom twee keer in hierdie Aliyah voor: Esav s’n en die land s’n.","Esav het sy honger laat besluit. Yitzchak is gesê om יהוה te laat besluit."],"action":"Bly getrou op een plek waar druk jou weg van gehoorsaamheid stoot.","detail":"Noem die “Egipte” wat nou na die maklike antwoord lyk: ’n kortpad by die werk, ’n kompromie in ’n verhouding of ’n vinnige oplossing met geld. Besluit vandag dat jy nie soontoe sal aftrek nie."}],"closing":"Honger gaan verby. ’n Eersgeboortereg kom nie terug nie.","actionOfDay":"Identifiseer voor vanaand een besluit wat jy op die punt staan om uit druk of aptyt te neem. Stel dit 24 uur uit en bring dit in gebed voor יהוה voordat jy optree.","waSummary":"Esav kom uitgeput in en verkoop sy eersgeboortereg vir brood en lensiesop aan Yaakov, en die teks sê dat hy dit verag het."}},{"date":"2026-11-09","parashah":"Toldot","year":"5787","aliyah":2,"ref":"Bereishit 26:6–12","en":{"title":"The Father’s Fear, Repeated","blessing":"Boker Tov! May today’s Aliyah free us from the fears we inherited.","hook":"Yitzchak repeated his father’s lie in the same city.","summary":"Yitzchak settles in Gerar, and when the men of the place ask about Rivkah, he says she is his sister because he fears they will kill him for her. After some time Avimelech sees from a window how Yitzchak treats Rivkah and confronts him: one of the people could easily have taken her, and Yitzchak would have brought guilt on them all. Avimelech orders that anyone who touches Yitzchak or his wife will be put to death. Yitzchak sows in the land and reaps a hundredfold that same year, and יהוה blesses him.","questions":[{"q":"What did Yitzchak say about Rivkah, and why?","ref":"26:6–7","answer":"He told the men of Gerar that she was his sister, because he feared they would kill him for her.","key":["His fear is spelled out in his own reasoning.","It is the same fear and the same answer, in the same city where Avraham said it (20:1–2)."],"action":"Name the fear behind your last half-truth.","detail":"Think of the last time you shaded the truth to protect yourself. Write down in one sentence what you were afraid would happen."},{"q":"How was the lie exposed?","ref":"26:8–10","answer":"Avimelech saw from a window how Yitzchak treated Rivkah, called him in, and confronted him with what his lie could have caused.","key":["A Philistine king had to name the danger: guilt on a whole people.","Deception rarely stays private. Others carry its risk."],"action":"Count who else carries the risk of your silence.","detail":"Take the half-truth you named in question 1. List the people who could be harmed if it continues, and decide what you will say to set it right."},{"q":"What does the Haftarah say belongs on the lips of one who walks with Elohim?","ref":"26:7; Malachi 2:5–6","answer":"In the Haftarah, יהוה describes His covenant with Levi: the Torah of truth was in his mouth, and no injustice was found on his lips.","key":["Malachi makes truthful speech a mark of walking with Elohim in peace and uprightness.","In Gerar, Yitzchak’s words fell short of that mark."],"action":"Read Malachi 2:4–7 and Bereishit 26:6–11 together.","detail":"Write down the qualities Malachi lists in the one who walks with Elohim. Choose one to practise in your speech today."},{"q":"Which of my parents’ patterns am I repeating without noticing?","ref":"26:7; 20:2","answer":"Yitzchak reached for the same self-protective answer his father had used.","key":["Patterns pass down as easily as blessings.","I need to name a family habit before it shapes my children."],"action":"Write down one reaction you learned at home that you do not want to pass on.","detail":"It may be how your family handled anger, money, conflict or the truth. Write the reaction, then write what obedience would look like instead."},{"q":"Where did the harvest come?","ref":"26:12","answer":"Yitzchak sowed in the land where יהוה had told him to stay and reaped a hundredfold that same year, and יהוה blessed him.","key":["The harvest came in the land of obedience, not in Egypt.","Staying where יהוה placed him became the place of increase."],"action":"Sow one thing today in the place where יהוה has put you.","detail":"Invest one concrete effort in your present family, work or congregation instead of waiting for a better place. Do it before the day ends."}],"closing":"Fear repeats itself. So can faithfulness.","actionOfDay":"Choose one area where you have shaded the truth to protect yourself. Before tonight, set it right with the person it affects.","waSummary":"In Gerar, Yitzchak says Rivkah is his sister out of fear, until Avimelech sees the truth and confronts him."},"af":{"title":"Die Vader se Vrees, Herhaal","blessing":"Boker Tov! Mag vandag se Aliyah ons vrymaak van die vrese wat ons geërf het.","hook":"Yitzchak het sy vader se leuen in dieselfde stad herhaal.","summary":"Yitzchak vestig hom in Gerar, en wanneer die manne van die plek na Rivkah vra, sê hy dat sy sy suster is, omdat hy vrees dat hulle hom ter wille van haar sal doodmaak. Ná ’n tyd sien Avimeleg deur ’n venster hoe Yitzchak met Rivkah omgaan en konfronteer hom: een van die mense kon haar maklik geneem het, en Yitzchak sou skuld oor hulle almal gebring het. Avimeleg beveel dat enigeen wat Yitzchak of sy vrou aanraak, doodgemaak sal word. Yitzchak saai in die land en oes dieselfde jaar honderdvoudig, en יהוה seën hom.","questions":[{"q":"Wat het Yitzchak oor Rivkah gesê, en hoekom?","ref":"26:6–7","answer":"Hy het vir die manne van Gerar gesê dat sy sy suster is, omdat hy gevrees het dat hulle hom ter wille van haar sou doodmaak.","key":["Sy vrees word in sy eie redenasie uitgespel.","Dit is dieselfde vrees en dieselfde antwoord, in dieselfde stad waar Avraham dit gesê het (20:1–2)."],"action":"Noem die vrees agter jou jongste halwe waarheid.","detail":"Dink aan die laaste keer toe jy die waarheid verbuig het om jouself te beskerm. Skryf in een sin neer waarvoor jy bang was."},{"q":"Hoe is die leuen ontbloot?","ref":"26:8–10","answer":"Avimeleg het deur ’n venster gesien hoe Yitzchak met Rivkah omgaan, hom geroep en hom gekonfronteer met wat sy leuen kon veroorsaak het.","key":["’n Filistynse koning moes die gevaar benoem: skuld oor ’n hele volk.","Misleiding bly selde privaat. Ander dra die risiko daarvan."],"action":"Tel wie anders die risiko van jou stilte dra.","detail":"Neem die halwe waarheid wat jy in vraag 1 genoem het. Lys die mense wat skade kan ly as dit voortduur, en besluit wat jy sal sê om dit reg te stel."},{"q":"Wat sê die Haftarah hoort op die lippe van een wat met Elohim wandel?","ref":"26:7; Maleagi 2:5–6","answer":"In die Haftarah beskryf יהוה sy verbond met Levi: die Torah van waarheid was in sy mond, en geen onreg is op sy lippe gevind nie.","key":["Maleagi maak eerlike spraak ’n kenmerk van wandel met Elohim in vrede en opregtheid.","In Gerar het Yitzchak se woorde by daardie maatstaf tekortgeskiet."],"action":"Lees Maleagi 2:4–7 en Bereishit 26:6–11 saam.","detail":"Skryf die eienskappe neer wat Maleagi noem by die een wat met Elohim wandel. Kies een om vandag in jou spraak in te oefen."},{"q":"Watter patrone van my ouers herhaal ek sonder om dit agter te kom?","ref":"26:7; 20:2","answer":"Yitzchak het na dieselfde selfbeskermende antwoord gegryp wat sy vader gebruik het.","key":["Patrone word net so maklik oorgedra soos seëninge.","Ek moet ’n familiegewoonte benoem voordat dit my kinders vorm."],"action":"Skryf een reaksie neer wat jy by die huis geleer het en nie wil oordra nie.","detail":"Dit kan wees hoe jou familie met woede, geld, konflik of die waarheid omgegaan het. Skryf die reaksie neer, en skryf dan neer hoe gehoorsaamheid eerder sou lyk."},{"q":"Waar het die oes gekom?","ref":"26:12","answer":"Yitzchak het gesaai in die land waar יהוה hom gesê het om te bly, en dieselfde jaar honderdvoudig geoes, en יהוה het hom geseën.","key":["Die oes het in die land van gehoorsaamheid gekom, nie in Egipte nie.","Om te bly waar יהוה hom geplaas het, het die plek van groei geword."],"action":"Saai vandag een ding op die plek waar יהוה jou gesit het.","detail":"Belê een konkrete poging in jou huidige gesin, werk of gemeente in plaas daarvan om vir ’n beter plek te wag. Doen dit voor die dag om is."}],"closing":"Vrees herhaal homself. Getrouheid ook.","actionOfDay":"Kies een terrein waar jy die waarheid verbuig het om jouself te beskerm. Stel dit voor vanaand reg met die persoon wat daardeur geraak word.","waSummary":"In Gerar sê Yitzchak uit vrees dat Rivkah sy suster is, totdat Avimeleg die waarheid sien en hom konfronteer."}},{"date":"2026-11-10","parashah":"Toldot","year":"5787","aliyah":3,"ref":"Bereishit 26:13–22","en":{"title":"Keep Digging","blessing":"Boker Tov! May today’s Aliyah give us the patience to keep digging.","hook":"Yitzchak kept digging until יהוה made room.","summary":"Yitzchak becomes very great, and the Philistines envy him; they have already stopped up the wells Avraham’s servants dug, filling them with earth. Avimelech sends him away, and Yitzchak settles in the valley of Gerar, where he digs out his father’s wells again and gives them the names his father gave them. His servants find a well of living water, but the herdsmen of Gerar claim it, so he names it Esek and digs another; they quarrel over that one too, and he names it Sitnah. He moves on and digs a third well that no one disputes, and names it Rechovot, saying that יהוה has made room for them to be fruitful in the land.","questions":[{"q":"What did Yitzchak do with the wells the Philistines had stopped?","ref":"26:15, 18","answer":"He dug them out again and called them by the same names his father had given them.","key":["He reopened what his father had opened.","He kept his father’s names on them."],"action":"Reopen one well your fathers in the faith dug.","detail":"Choose one practice handed down to you that has fallen silent, such as a blessing at the table, a prayer or a Scripture you once knew by heart. Restore it this week."},{"q":"Why did Yitzchak move on from Esek and Sitnah?","ref":"26:20–22","answer":"Each time the herdsmen of Gerar claimed the water, he named the well after the strife and dug another, until he found one that no one disputed.","key":["Esek means contention, Sitnah means hostility, and Rechovot means wide spaces.","He did not fight for every well. Room came after he moved on."],"action":"Name your Esek and your Sitnah.","detail":"Identify one conflict you keep returning to over something that is not essential. Write down what you would gain by digging elsewhere."},{"q":"How does Yeshua speak of living water?","ref":"26:19; Yochanan 4:10–14","answer":"At Yaakov’s well, Yeshua tells the Samaritan woman that the water He gives becomes a spring of water within, welling up to everlasting life.","key":["Yitzchak’s servants found a well of living water in the valley.","The wells of the fathers point to the water only יהוה gives."],"action":"Read Yochanan 4:5–14 beside Bereishit 26:17–22.","detail":"Notice whose well the conversation takes place at. Write one sentence on what that tells you about how the Brit Chadashah grows out of the Tanach."},{"q":"Which well of truth have I let others fill with earth?","ref":"26:15, 18","answer":"After Avraham died, the Philistines filled his wells with earth.","key":["What the fathers opened can be closed by neglect and hostility.","Reopening takes work, not nostalgia."],"action":"Clear one thing that has buried a truth you once held.","detail":"It may be an opinion you absorbed, a habit that crowded out study, or a voice you let speak louder than the Word. Remove or reduce it this week."},{"q":"Am I willing to move on from a quarrel instead of winning it?","ref":"26:20–22","answer":"Twice Yitzchak let a disputed well go and dug again.","key":["His answer to strife was another shovel, not another argument.","Rechovot came after he let go."],"action":"Step back from one argument over something that is not essential.","detail":"Tell the other person plainly that you are letting the matter go, and put your energy into something that builds instead."}],"closing":"The Philistines filled the wells. Yitzchak kept digging.","actionOfDay":"Choose one practice of faith that neglect has filled in, such as the Shabbat table, family prayer or reading the Torah portion. Restart it this week, and set the day and time now.","waSummary":"Yitzchak reopens his father’s wells and keeps digging past every quarrel until he finds a well no one disputes: Rechovot."},"af":{"title":"Hou Aan Grawe","blessing":"Boker Tov! Mag vandag se Aliyah ons die geduld gee om aan te hou grawe.","hook":"Yitzchak het aangehou grawe totdat יהוה ruimte gemaak het.","summary":"Yitzchak word baie groot, en die Filistyne is jaloers op hom; hulle het reeds die putte wat Avraham se dienaars gegrawe het, toegestop en met grond gevul. Avimeleg stuur hom weg, en Yitzchak vestig hom in die laagte van Gerar, waar hy sy vader se putte weer oopgrawe en hulle die name gee wat sy vader hulle gegee het. Sy dienaars kry ’n put met lewende water, maar die veewagters van Gerar eis dit op, en hy noem dit Esek en grawe ’n ander een; hulle twis ook oor dié een, en hy noem dit Sitnah. Hy trek verder en grawe ’n derde put waaroor niemand twis nie, en noem dit Rechovot, omdat יהוה vir hulle ruimte gemaak het om vrugbaar te wees in die land.","questions":[{"q":"Wat het Yitzchak gedoen met die putte wat die Filistyne toegestop het?","ref":"26:15, 18","answer":"Hy het hulle weer oopgegrawe en hulle dieselfde name gegee wat sy vader hulle gegee het.","key":["Hy het heropen wat sy vader oopgemaak het.","Hy het sy vader se name daarop behou."],"action":"Heropen een put wat jou vaders in die geloof gegrawe het.","detail":"Kies een gebruik wat aan jou oorgedra is en stil geword het, soos ’n seën aan tafel, ’n gebed of ’n Skrifgedeelte wat jy eens uit jou kop geken het. Herstel dit hierdie week."},{"q":"Hoekom het Yitzchak van Esek en Sitnah af verder getrek?","ref":"26:20–22","answer":"Elke keer wat die veewagters van Gerar die water opgeëis het, het hy die put na die twis vernoem en ’n ander een gegrawe, totdat hy een gekry het waaroor niemand getwis het nie.","key":["Esek beteken twis, Sitnah beteken vyandskap, en Rechovot beteken wye ruimtes.","Hy het nie vir elke put geveg nie. Die ruimte het gekom nadat hy verder getrek het."],"action":"Noem jou Esek en jou Sitnah.","detail":"Identifiseer een konflik waarna jy telkens terugkeer oor iets wat nie wesenlik is nie. Skryf neer wat jy sou wen as jy elders grawe."},{"q":"Hoe praat Yeshua van lewende water?","ref":"26:19; Yochanan 4:10–14","answer":"By Yaakov se put sê Yeshua vir die Samaritaanse vrou dat die water wat Hy gee, ’n fontein in haar word wat opborrel tot die ewige lewe.","key":["Yitzchak se dienaars het in die laagte ’n put met lewende water gekry.","Die putte van die vaders wys na die water wat net יהוה gee."],"action":"Lees Yochanan 4:5–14 saam met Bereishit 26:17–22.","detail":"Let op by wie se put die gesprek plaasvind. Skryf een sin oor wat dit jou leer oor hoe die Brit Chadashah uit die Tanach groei."},{"q":"Watter put van waarheid het ek toegelaat dat ander met grond vul?","ref":"26:15, 18","answer":"Nadat Avraham dood is, het die Filistyne sy putte met grond gevul.","key":["Wat die vaders oopgemaak het, kan deur verwaarlosing en vyandskap toegemaak word.","Om te heropen verg werk, nie nostalgie nie."],"action":"Ruim een ding op wat ’n waarheid begrawe het wat jy eens vasgehou het.","detail":"Dit kan ’n mening wees wat jy oorgeneem het, ’n gewoonte wat studie verdring het, of ’n stem wat jy harder as die Woord laat praat het. Verwyder of beperk dit hierdie week."},{"q":"Is ek bereid om van ’n twis af weg te stap eerder as om dit te wen?","ref":"26:20–22","answer":"Twee keer het Yitzchak ’n betwiste put laat gaan en weer gegrawe.","key":["Sy antwoord op twis was nog ’n graaf, nie nog ’n argument nie.","Rechovot het gekom nadat hy losgelaat het."],"action":"Tree terug uit een argument oor iets wat nie wesenlik is nie.","detail":"Sê vir die ander persoon reguit dat jy die saak laat gaan, en sit jou energie in iets wat opbou."}],"closing":"Die Filistyne het die putte gevul. Yitzchak het aangehou grawe.","actionOfDay":"Kies een geloofsgebruik wat verwaarlosing toegegooi het, soos die Shabbat-tafel, gesinsgebed of die lees van die Torahgedeelte. Begin dit hierdie week weer, en stel die dag en tyd nou vas.","waSummary":"Yitzchak grawe sy vader se putte weer oop en hou aan grawe ná elke twis, totdat hy ’n put kry waaroor niemand twis nie: Rechovot."}},{"date":"2026-11-11","parashah":"Toldot","year":"5787","aliyah":4,"ref":"Bereishit 26:23–29","en":{"title":"They Saw That יהוה Was With Him","blessing":"Boker Tov! May today’s Aliyah put worship before everything we build.","hook":"The men who drove Yitzchak away came back because they saw יהוה with him.","summary":"Yitzchak goes up to Beer-Sheva, and that night יהוה appears to him as the Elohim of Avraham his father and tells him not to fear, because He is with him and will bless him. Yitzchak builds an altar there, calls on the Name of יהוה, pitches his tent, and his servants dig a well. Avimelech comes from Gerar with his adviser and the commander of his army, and Yitzchak asks why they have come, since they hated him and sent him away. They answer that they have clearly seen that יהוה is with him, and ask for an oath and a covenant of peace between them.","questions":[{"q":"What did Yitzchak do after יהוה appeared to him at Beer-Sheva?","ref":"26:23–25","answer":"He built an altar, called on the Name of יהוה, pitched his tent there, and his servants dug a well.","key":["Altar first, tent second, well third.","Worship came before settling and before providing."],"action":"Put worship first in the order of your day.","detail":"Before you open messages or start work tomorrow, spend the first ten minutes in prayer and the Word."},{"q":"Why does יהוה say “Do not fear” at Beer-Sheva?","ref":"26:24","answer":"After the strife over the wells, יהוה tells Yitzchak that He is the Elohim of Avraham his father, that He is with him, and that He will bless him for Avraham’s sake.","key":["The promise is anchored in who יהוה has already been to his father.","Fear is answered with presence: I am with you."],"action":"Write down what יהוה has already been to those before you.","detail":"List three ways יהוה proved faithful to your parents, your teachers or the believers who brought you the truth. Read the list when fear rises."},{"q":"How does Yeshua describe the witness others see?","ref":"26:28; Mattityahu 5:14–16","answer":"Yeshua tells His disciples to let their light shine before others, so that they see their good works and glorify their Father in heaven.","key":["Avimelech’s men did not quote Yitzchak’s claims. They described what they had seen.","Testimony is what others observe, not only what we say."],"action":"Read Mattityahu 5:14–16 beside Bereishit 26:26–29.","detail":"Ask what the people around you could honestly say they have seen in your life this month."},{"q":"Can those who opposed me see יהוה with me?","ref":"26:27–28","answer":"Yitzchak’s former opponents said they had clearly seen that יהוה was with him.","key":["His conduct after being sent away became the evidence.","Hostility tests what people can see in me."],"action":"Treat someone who opposed you in a way that reflects יהוה.","detail":"Choose one person who has been against you. Do one fair, honest act toward them this week without expecting anything back."},{"q":"Will I listen to the people who hurt me?","ref":"26:27–29","answer":"Yitzchak named their hostility openly, and then listened to their proposal of peace.","key":["He did not pretend the past had not happened.","He still let them speak."],"action":"Hear out one person who wronged you, with the past named honestly.","detail":"If someone who hurt you is reaching out, agree to talk. Say plainly what happened, then listen fully before you answer."}],"closing":"Yitzchak built an altar before he dug a well.","actionOfDay":"Build your altar first today: before work, messages or plans, spend ten minutes in prayer and the Word, then begin the day.","waSummary":"At Beer-Sheva Yitzchak builds an altar, and the men who sent him away come to make peace because they saw יהוה with him."},"af":{"title":"Hulle Het Gesien dat יהוה by Hom Was","blessing":"Boker Tov! Mag vandag se Aliyah aanbidding vóór alles plaas wat ons bou.","hook":"Die manne wat Yitzchak weggejaag het, het teruggekom omdat hulle gesien het dat יהוה by hom is.","summary":"Yitzchak trek op na Be’er-Sheva, en daardie nag verskyn יהוה aan hom as die Elohim van sy vader Avraham en sê vir hom om nie te vrees nie, want Hy is by hom en sal hom seën. Yitzchak bou daar ’n altaar, roep die Naam van יהוה aan, slaan sy tent op, en sy dienaars grawe ’n put. Avimeleg kom van Gerar af saam met sy raadgewer en die bevelhebber van sy leër, en Yitzchak vra hoekom hulle gekom het, aangesien hulle hom gehaat en weggestuur het. Hulle antwoord dat hulle duidelik gesien het dat יהוה by hom is, en vra vir ’n eed en ’n vredesverbond tussen hulle.","questions":[{"q":"Wat het Yitzchak gedoen nadat יהוה by Be’er-Sheva aan hom verskyn het?","ref":"26:23–25","answer":"Hy het ’n altaar gebou, die Naam van יהוה aangeroep, sy tent daar opgeslaan, en sy dienaars het ’n put gegrawe.","key":["Eers die altaar, dan die tent, dan die put.","Aanbidding het gekom voordat hy hom gevestig en voorsien het."],"action":"Sit aanbidding eerste in die volgorde van jou dag.","detail":"Voordat jy môre boodskappe oopmaak of begin werk, bestee die eerste tien minute aan gebed en die Woord."},{"q":"Hoekom sê יהוה by Be’er-Sheva: “Moenie vrees nie”?","ref":"26:24","answer":"Ná die twis oor die putte sê יהוה vir Yitzchak dat Hy die Elohim van sy vader Avraham is, dat Hy by hom is, en dat Hy hom ter wille van Avraham sal seën.","key":["Die belofte is geanker in wie יהוה reeds vir sy vader was.","Vrees word met teenwoordigheid beantwoord: Ek is by jou."],"action":"Skryf neer wat יהוה reeds was vir dié wat voor jou gegaan het.","detail":"Lys drie maniere waarop יהוה getrou was aan jou ouers, jou leermeesters of die gelowiges wat die waarheid na jou gebring het. Lees die lys wanneer vrees opkom."},{"q":"Hoe beskryf Yeshua die getuienis wat ander sien?","ref":"26:28; Mattityahu 5:14–16","answer":"Yeshua sê vir sy dissipels om hulle lig voor ander te laat skyn, sodat hulle hul goeie werke kan sien en hul Vader in die hemel verheerlik.","key":["Avimeleg se manne het nie Yitzchak se aansprake aangehaal nie. Hulle het beskryf wat hulle gesien het.","Getuienis is wat ander waarneem, nie net wat ons sê nie."],"action":"Lees Mattityahu 5:14–16 saam met Bereishit 26:26–29.","detail":"Vra wat die mense om jou eerlik kan sê hulle hierdie maand in jou lewe gesien het."},{"q":"Kan dié wat my teengestaan het, sien dat יהוה by my is?","ref":"26:27–28","answer":"Yitzchak se voormalige teenstanders het gesê dat hulle duidelik gesien het dat יהוה by hom is.","key":["Sy optrede nadat hy weggestuur is, het die bewys geword.","Vyandigheid toets wat mense in my kan sien."],"action":"Behandel iemand wat jou teengestaan het op ’n manier wat יהוה weerspieël.","detail":"Kies een persoon wat teen jou was. Doen hierdie week een regverdige, eerlike daad teenoor hulle sonder om iets terug te verwag."},{"q":"Sal ek luister na die mense wat my seergemaak het?","ref":"26:27–29","answer":"Yitzchak het hulle vyandigheid openlik benoem en toe na hulle voorstel van vrede geluister.","key":["Hy het nie voorgegee dat die verlede nie gebeur het nie.","Hy het hulle steeds laat praat."],"action":"Luister na een persoon wat jou onreg aangedoen het, met die verlede eerlik benoem.","detail":"As iemand wat jou seergemaak het, uitreik, stem in om te praat. Sê reguit wat gebeur het, en luister dan volledig voordat jy antwoord."}],"closing":"Yitzchak het ’n altaar gebou voordat hy ’n put gegrawe het.","actionOfDay":"Bou vandag eers jou altaar: voor werk, boodskappe of planne, bestee tien minute aan gebed en die Woord, en begin dan die dag.","waSummary":"Yitzchak bou ’n altaar by Be’er-Sheva, en sy teenstanders kom vrede maak omdat יהוה by hom is."}},{"date":"2026-11-12","parashah":"Toldot","year":"5787","aliyah":5,"ref":"Bereishit 26:30–27:27","en":{"title":"The Voice and the Hands","blessing":"Boker Tov! May today’s Aliyah make our voice and our hands agree.","hook":"The voice was Yaakov’s; the hands were dressed as Esav’s.","summary":"Yitzchak makes a feast for Avimelech, they swear an oath of peace, and that same day his servants find water at Beer-Sheva. Esav marries two Hittite women, who are a grief to Yitzchak and Rivkah. When Yitzchak is old and his eyes are dim, he sends Esav to hunt and prepare a meal so that he may bless him; Rivkah overhears and tells Yaakov to bring two young goats so that she can prepare the meal and he can receive the blessing instead. Dressed in Esav’s clothes, with goat skins on his hands and neck, Yaakov tells his father he is Esav; Yitzchak hesitates over the voice, but after touching, eating and smelling Esav’s garments, he blesses him.","questions":[{"q":"What did Yaakov say when his father asked who he was?","ref":"27:18–20","answer":"He said he was Esav the firstborn, and when asked how he found game so quickly, he said יהוה his father’s Elohim had brought it to him.","key":["He used the Name of יהוה to support a lie.","The deception reached even his words about Elohim."],"action":"Check your speech about Elohim today.","detail":"Notice each time you say that יהוה led, opened or provided. Make sure it is true, and not a way of covering your own plan."},{"q":"Why did Yitzchak’s doubt not stop the blessing?","ref":"27:21–27","answer":"He noticed that the voice was Yaakov’s, but the feel of the hands, the taste of the meal and the smell of the garments persuaded him.","key":["He trusted what he could touch, taste and smell over what he heard.","Every step of the plan worked through the senses."],"action":"Test one decision by what you hear, not only by what feels right.","detail":"Before you decide something important this week, write down what the Word actually says about it, and let that weigh more than your impression."},{"q":"What does the Haftarah ask about a son’s honour?","ref":"27:19; Malachi 1:6","answer":"In the Haftarah, יהוה says that a son honours his father, and asks: if I am a Father, where is My honour?","key":["Yaakov came to his father in another man’s name and another man’s clothes.","Malachi asks whether we bring honest honour to our Father in heaven."],"action":"Read Malachi 1:6–8 beside Bereishit 27:18–24.","detail":"Write down one way you could honour your Father in heaven more honestly this week."},{"q":"Have I used the Name of יהוה to cover my own plan?","ref":"27:20","answer":"Yaakov credited יהוה with a meal that came from his mother’s kitchen.","key":["Spiritual language can dress up a deception.","I need to check whether I say “יהוה led me” about decisions I engineered."],"action":"Name one decision you have dressed in spiritual language.","detail":"Write it down honestly, as it really happened. If you told others that יהוה led you, consider whether you need to correct that."},{"q":"Whose voice am I obeying?","ref":"27:8, 11–13","answer":"Rivkah twice told Yaakov to obey her voice, and took any curse upon herself; Yaakov objected only that he might be caught.","key":["Yaakov raised the risk. He did not raise the question of right and wrong.","His concern was being caught, not being wrong."],"action":"Ask whether a plan is right, not only whether it will work.","detail":"Before you follow anyone’s plan this week, however close they are to you, ask aloud: is this right before יהוה?"}],"closing":"Yaakov feared being caught more than being wrong.","actionOfDay":"Before you agree to a plan today, ask one question aloud: is this right before יהוה, or only likely to work? If it is only the second, stop.","waSummary":"Dressed in Esav’s clothes, Yaakov tells his blind father he is Esav, and Yitzchak blesses him."},"af":{"title":"Die Stem en die Hande","blessing":"Boker Tov! Mag vandag se Aliyah ons stem en ons hande laat ooreenstem.","hook":"Die stem was Yaakov s’n; die hande was soos Esav s’n aangetrek.","summary":"Yitzchak berei ’n maaltyd vir Avimeleg, hulle sweer ’n eed van vrede, en dieselfde dag kry sy dienaars water by Be’er-Sheva. Esav trou met twee Hetitiese vroue, wat vir Yitzchak en Rivkah ’n bitter smart is. Wanneer Yitzchak oud is en sy oë dof geword het, stuur hy Esav om te gaan jag en ’n maaltyd te berei sodat hy hom kan seën; Rivkah hoor dit en sê vir Yaakov om twee bokkies te bring sodat sy die maaltyd kan berei en hy eerder die seën kan ontvang. Aangetrek in Esav se klere, met bokvelle oor sy hande en nek, sê Yaakov vir sy vader dat hy Esav is; Yitzchak huiwer oor die stem, maar nadat hy hom gevoel, geëet en Esav se klere geruik het, seën hy hom.","questions":[{"q":"Wat het Yaakov gesê toe sy vader vra wie hy is?","ref":"27:18–20","answer":"Hy het gesê hy is Esav, die eersgeborene, en toe gevra word hoe hy die wild so gou gekry het, het hy gesê dat יהוה, sy vader se Elohim, dit na hom gebring het.","key":["Hy het die Naam van יהוה gebruik om ’n leuen te stut.","Die misleiding het selfs sy woorde oor Elohim bereik."],"action":"Kontroleer vandag jou woorde oor Elohim.","detail":"Let op elke keer wat jy sê dat יהוה gelei, oopgemaak of voorsien het. Maak seker dit is waar, en nie ’n manier om jou eie plan te bedek nie."},{"q":"Hoekom het Yitzchak se twyfel nie die seën gekeer nie?","ref":"27:21–27","answer":"Hy het opgemerk dat die stem Yaakov s’n was, maar die gevoel van die hande, die smaak van die maaltyd en die reuk van die klere het hom oortuig.","key":["Hy het vertrou op wat hy kon voel, proe en ruik, bo wat hy gehoor het.","Elke stap van die plan het deur die sintuie gewerk."],"action":"Toets een besluit aan wat jy hoor, nie net aan wat reg voel nie.","detail":"Voordat jy hierdie week iets belangriks besluit, skryf neer wat die Woord werklik daaroor sê, en laat dit swaarder weeg as jou indruk."},{"q":"Wat vra die Haftarah oor ’n seun se eer?","ref":"27:19; Maleagi 1:6","answer":"In die Haftarah sê יהוה dat ’n seun sy vader eer, en vra: as Ek ’n Vader is, waar is my eer?","key":["Yaakov het na sy vader gekom in ’n ander man se naam en ’n ander man se klere.","Maleagi vra of ons eerlike eer aan ons Vader in die hemel bring."],"action":"Lees Maleagi 1:6–8 saam met Bereishit 27:18–24.","detail":"Skryf een manier neer waarop jy jou Vader in die hemel hierdie week eerliker kan eer."},{"q":"Het ek die Naam van יהוה gebruik om my eie plan te bedek?","ref":"27:20","answer":"Yaakov het יהוה die eer gegee vir ’n maaltyd wat uit sy moeder se kombuis gekom het.","key":["Geestelike taal kan ’n misleiding aantrek.","Ek moet nagaan of ek sê “יהוה het my gelei” oor besluite wat ek self bewerkstellig het."],"action":"Noem een besluit wat jy in geestelike taal geklee het.","detail":"Skryf dit eerlik neer, soos dit werklik gebeur het. As jy vir ander gesê het dat יהוה jou gelei het, oorweeg of jy dit moet regstel."},{"q":"Na wie se stem luister ek?","ref":"27:8, 11–13","answer":"Rivkah het Yaakov twee keer gesê om na haar stem te luister en enige vloek op haarself geneem; Yaakov se enigste beswaar was dat hy dalk uitgevang sou word.","key":["Yaakov het die risiko genoem. Hy het nie die vraag van reg en verkeerd genoem nie.","Sy kommer was om uitgevang te word, nie om verkeerd te wees nie."],"action":"Vra of ’n plan reg is, nie net of dit sal werk nie.","detail":"Voordat jy hierdie week iemand se plan volg, hoe na hulle ook al aan jou is, vra hardop: is dit reg voor יהוה?"}],"closing":"Yaakov was banger om uitgevang te word as om verkeerd te wees.","actionOfDay":"Voordat jy vandag tot ’n plan instem, vra hardop een vraag: is dit reg voor יהוה, of sal dit net waarskynlik werk? As dit net die tweede is, stop.","waSummary":"In Esav se klere sê Yaakov vir sy blinde vader dat hy Esav is, en Yitzchak seën hom."}},{"date":"2026-11-13","parashah":"Toldot","year":"5787","aliyah":6,"ref":"Bereishit 27:28–28:4","en":{"title":"A Great and Bitter Cry","blessing":"Boker Tov! May today’s Aliyah teach us to value the blessing before it is gone.","hook":"Esav wept for the blessing after he had despised the birthright.","summary":"Yitzchak blesses Yaakov with the dew of heaven, the richness of the earth and rule over his brothers. As soon as Yaakov leaves, Esav arrives with his meal; Yitzchak trembles greatly but confirms that the one he blessed will be blessed, and Esav cries out with a great and bitter cry and receives only a lesser word. Esav resolves in his heart to kill Yaakov once the days of mourning for their father come, so Rivkah sends Yaakov to her brother Lavan in Charan. Yitzchak calls Yaakov, commands him not to take a wife from the daughters of Canaan, and blesses him with the blessing of Avraham.","questions":[{"q":"What did Yitzchak do when he realised what had happened?","ref":"27:30–33","answer":"He trembled exceedingly, and then confirmed that the one he had blessed would indeed be blessed.","key":["He did not take the blessing back.","Even in shock, he let his spoken word stand."],"action":"Keep one promise you are tempted to withdraw.","detail":"Think of a commitment you made that has become inconvenient. Honour it this week."},{"q":"Why could Esav not get the first blessing back?","ref":"27:34–40","answer":"Yitzchak said he had already made Yaakov lord over him and sustained him with grain and wine; what remained for Esav was a lesser word.","key":["Esav cried out with a great and bitter cry.","His tears came after his choices, not before them."],"action":"Grieve your losses honestly, but learn from them before the next choice.","detail":"Name one consequence you are living with now. Write down the choice that led to it, and what you will do differently next time."},{"q":"How does Paul read the older serving the younger?","ref":"25:23; Malachi 1:2–3; Romans 9:10–13","answer":"Paul joins Bereishit 25:23 and Malachi 1:2–3 to show that the choice of Yaakov over Esav rests on the purpose of Elohim who calls, not on works.","key":["The older serving the younger was spoken before the twins were born.","Malachi, this week’s Haftarah, repeats it centuries later."],"action":"Read Romans 9:6–16 with Bereishit 25:21–23 and Malachi 1:2–3 open.","detail":"Mark where Paul quotes the Tanach. Write one sentence on what this teaches you about the calling of Elohim."},{"q":"Is my hatred waiting for a better time?","ref":"27:41","answer":"Esav decided in his heart to kill Yaakov after the days of mourning for his father.","key":["His hatred had a timetable.","Postponed revenge is still revenge."],"action":"Cancel one plan to “deal with someone later.”","detail":"Name the person you have been waiting to get even with. Bring the matter before יהוה in prayer and release the plan."},{"q":"What did Yitzchak require of Yaakov when he sent him with the blessing of Avraham?","ref":"28:1–4","answer":"He commanded Yaakov not to take a wife from the daughters of Canaan but from his mother’s family, and blessed him with the blessing of Avraham.","key":["The blessing came with a command about whom to marry.","The covenant shapes ordinary choices like marriage."],"action":"Bring one major relationship decision under the instruction of Scripture.","detail":"If you or someone you guide is facing a decision about marriage or a close partnership, read what the Torah and the Brit Chadashah say about it before going further."}],"closing":"Tears could not buy back what appetite had sold.","actionOfDay":"Name the person you have been planning to “deal with later.” Before Shabbat begins tonight, release that plan before יהוה in prayer and take one step toward peace.","waSummary":"Esav arrives too late and cries out bitterly for the blessing, then plans to kill Yaakov, who is sent away to Lavan."},"af":{"title":"’n Groot en Bitter Geroep","blessing":"Boker Tov! Mag vandag se Aliyah ons leer om die seën te waardeer voordat dit weg is.","hook":"Esav het oor die seën gehuil nadat hy die eersgeboortereg verag het.","summary":"Yitzchak seën Yaakov met die dou van die hemel, die vettigheid van die aarde en heerskappy oor sy broers. Net toe Yaakov uitgaan, kom Esav met sy maaltyd; Yitzchak bewe hewig, maar bevestig dat die een wat hy geseën het, geseën sal wees, en Esav skreeu ’n groot en bitter geroep en ontvang net ’n mindere woord. Esav besluit in sy hart om Yaakov dood te maak sodra die dae van rou oor hulle vader aanbreek, en daarom stuur Rivkah vir Yaakov na haar broer Lavan in Charan. Yitzchak roep Yaakov, beveel hom om nie ’n vrou uit die dogters van Kanaän te neem nie, en seën hom met die seën van Avraham.","questions":[{"q":"Wat het Yitzchak gedoen toe hy besef wat gebeur het?","ref":"27:30–33","answer":"Hy het hewig gebewe, en toe bevestig dat die een wat hy geseën het, inderdaad geseën sal wees.","key":["Hy het die seën nie teruggeneem nie.","Selfs in skok het hy sy gesproke woord laat staan."],"action":"Hou een belofte wat jy in die versoeking is om terug te trek.","detail":"Dink aan ’n verbintenis wat jy gemaak het en wat ongerieflik geword het. Kom dit hierdie week na."},{"q":"Hoekom kon Esav nie die eerste seën terugkry nie?","ref":"27:34–40","answer":"Yitzchak het gesê dat hy Yaakov reeds heer oor hom gemaak en hom met koring en wyn versorg het; wat vir Esav oorgebly het, was ’n mindere woord.","key":["Esav het ’n groot en bitter geroep uitgeskreeu.","Sy trane het ná sy keuses gekom, nie voor hulle nie."],"action":"Rou eerlik oor jou verliese, maar leer daaruit voor die volgende keuse.","detail":"Noem een gevolg waarmee jy nou saamleef. Skryf die keuse neer wat daartoe gelei het, en wat jy volgende keer anders sal doen."},{"q":"Hoe lees Paulus dat die oudste die jongste sal dien?","ref":"25:23; Maleagi 1:2–3; Romeine 9:10–13","answer":"Paulus verbind Bereishit 25:23 en Maleagi 1:2–3 om te wys dat die keuse van Yaakov bo Esav berus op die voorneme van Elohim wat roep, nie op werke nie.","key":["Dat die oudste die jongste sal dien, is gespreek voordat die tweeling gebore is.","Maleagi, hierdie week se Haftarah, herhaal dit eeue later."],"action":"Lees Romeine 9:6–16 met Bereishit 25:21–23 en Maleagi 1:2–3 oop.","detail":"Merk waar Paulus die Tanach aanhaal. Skryf een sin oor wat dit jou leer oor die roeping van Elohim."},{"q":"Wag my haat vir ’n beter tyd?","ref":"27:41","answer":"Esav het in sy hart besluit om Yaakov dood te maak ná die dae van rou oor sy vader.","key":["Sy haat het ’n tydrooster gehad.","Uitgestelde wraak is steeds wraak."],"action":"Kanselleer een plan om iemand “later te hanteer.”","detail":"Noem die persoon met wie jy gewag het om gelyk te kry. Bring die saak in gebed voor יהוה en laat die plan los."},{"q":"Wat het Yitzchak van Yaakov vereis toe hy hom met die seën van Avraham weggestuur het?","ref":"28:1–4","answer":"Hy het Yaakov beveel om nie ’n vrou uit die dogters van Kanaän te neem nie, maar uit sy moeder se familie, en hom met die seën van Avraham geseën.","key":["Die seën het gekom met ’n gebod oor met wie om te trou.","Die verbond vorm gewone keuses soos die huwelik."],"action":"Bring een groot verhoudingsbesluit onder die onderrig van die Skrif.","detail":"As jy of iemand wat jy begelei, voor ’n besluit oor ’n huwelik of ’n nou vennootskap staan, lees wat die Torah en die Brit Chadashah daaroor sê voordat julle verder gaan."}],"closing":"Trane kon nie terugkoop wat aptyt verkoop het nie.","actionOfDay":"Noem die persoon wat jy van plan was om “later te hanteer.” Laat daardie plan voor Shabbat vanaand begin in gebed voor יהוה los, en neem een tree na vrede.","waSummary":"Esav kom te laat en skreeu bitterlik om die seën, en beplan dan om Yaakov dood te maak, wat na Lavan weggestuur word."}},{"date":"2026-11-14","parashah":"Toldot","year":"5787","aliyah":7,"ref":"Bereishit 28:5–9","en":{"title":"Pleasing or Obeying","blessing":"Boker Tov and Shabbat Shalom! May today’s Aliyah teach us to obey, not merely to please.","hook":"Esav tried to please his father by adding a wife instead of changing his ways.","summary":"Yitzchak sends Yaakov away, and he goes to Paddan-Aram, to Lavan son of Betuel the Aramean, the brother of Rivkah. Esav sees that his father has blessed Yaakov and charged him not to take a Canaanite wife, and that Yaakov obeyed his father and mother and went. Realising that the daughters of Canaan displease his father, Esav goes to Yishmael and takes Machalat, Yishmael’s daughter, as a wife, in addition to the wives he already has.","questions":[{"q":"What did Yaakov do after his father’s charge?","ref":"28:5, 7","answer":"He obeyed his father and his mother and went to Paddan-Aram.","key":["The text names his obedience to both parents.","He left home with the blessing and the instruction."],"action":"Carry out one instruction from a parent or elder that agrees with Scripture.","detail":"Think of counsel you received from a parent, elder or teacher that you know is right but have not acted on. Take the first step this week."},{"q":"What did Esav learn from watching Yaakov, and what did he do with it?","ref":"28:6–9","answer":"He saw that the daughters of Canaan displeased his father, so he took a daughter of Yishmael as a wife, in addition to the wives he already had.","key":["He observed the right lesson and applied it the wrong way.","He added to his choices instead of turning from them."],"action":"Look for the change behind the lesson, not only the gesture.","detail":"Think of a correction you received recently. Ask what real change it calls for, not just what would look better."},{"q":"What does the Haftarah say about offerings that cost little?","ref":"28:9; Malachi 1:7–8","answer":"In the Haftarah, יהוה rebukes the priests for bringing blind and lame animals as offerings, and asks whether their governor would accept such a gift.","key":["Esav also tried to please with something that cost him little.","Pleasing Elohim is not a matter of adding a gesture, but of giving what He asked."],"action":"Read Malachi 1:6–11 beside Bereishit 28:6–9.","detail":"Write down one area where you give יהוה what is left over instead of what is first and best."},{"q":"Am I trying to please with additions instead of repentance?","ref":"28:9","answer":"Esav took Machalat in addition to the Hittite wives who had grieved his parents.","key":["His solution left the original problem in place.","I can add a religious habit without letting go of what grieves Elohim."],"action":"Name one thing you have added to ease your conscience.","detail":"Then name what it was meant to cover. Bring that real issue before יהוה honestly."},{"q":"Will I go where obedience sends me?","ref":"28:5","answer":"Yitzchak sent Yaakov away, and Yaakov went.","key":["Obedience sometimes means leaving what is familiar.","He went with the blessing and the charge his father gave him."],"action":"Take one step this week in the direction obedience has been pointing you.","detail":"Name the move, conversation or commitment you know you are called to. Set a date for the first step."}],"deeper":"The Haftarah, Malachi 1:1–2:7, opens where this Parashah ends: יהוה declares that He loved Yaakov and rejected Esav, and that Edom will build but He will tear down (Malachi 1:2–4). It then rebukes priests who despise His Name with blemished offerings (1:6–8), the same failing as Esav, who despised his birthright (Bereishit 25:34), and holds up the covenant with Levi, in whose mouth was the Torah of truth (2:5–7). Paul brings Bereishit 25:23 and Malachi 1:2–3 together in Romans 9:10–13 to show that the choice rests on the purpose of Elohim who calls. Hebrews 12:16–17 turns the whole Parashah into a warning: do not be like Esav, who sold his birthright for a single meal.","closing":"Esav added a wife. Yaakov obeyed and went.","actionOfDay":"This Shabbat, name one thing you have added to your life to ease your conscience instead of turning from what grieves יהוה. Write down the real step of repentance, and take it on the first day of the week.","waSummary":"Yaakov obeys his parents and leaves for Paddan-Aram, while Esav adds a daughter of Yishmael to his wives to please his father."},"af":{"title":"Behaag of Gehoorsaam","blessing":"Boker Tov en Shabbat Shalom! Mag vandag se Aliyah ons leer om te gehoorsaam, nie net om te behaag nie.","hook":"Esav het probeer om sy vader te behaag deur ’n vrou by te voeg in plaas daarvan om sy weë te verander.","summary":"Yitzchak stuur Yaakov weg, en hy gaan na Paddan-Aram, na Lavan, die seun van Betuél die Arameër, die broer van Rivkah. Esav sien dat sy vader Yaakov geseën het en hom beveel het om nie ’n Kanaänitiese vrou te neem nie, en dat Yaakov na sy vader en moeder geluister en gegaan het. Wanneer Esav besef dat die dogters van Kanaän sy vader mishaag, gaan hy na Yishmael en neem Machalat, Yishmael se dogter, as vrou, bo en behalwe die vroue wat hy reeds het.","questions":[{"q":"Wat het Yaakov gedoen ná sy vader se opdrag?","ref":"28:5, 7","answer":"Hy het na sy vader en sy moeder geluister en na Paddan-Aram gegaan.","key":["Die teks noem sy gehoorsaamheid aan albei ouers.","Hy het die huis verlaat met die seën en die opdrag."],"action":"Voer een opdrag uit van ’n ouer of ouderling wat met die Skrif ooreenstem.","detail":"Dink aan raad wat jy van ’n ouer, ouderling of leermeester ontvang het wat jy weet reg is, maar waarop jy nog nie opgetree het nie. Neem hierdie week die eerste tree."},{"q":"Wat het Esav geleer deur na Yaakov te kyk, en wat het hy daarmee gedoen?","ref":"28:6–9","answer":"Hy het gesien dat die dogters van Kanaän sy vader mishaag, en daarom het hy ’n dogter van Yishmael as vrou geneem, bo en behalwe die vroue wat hy reeds gehad het.","key":["Hy het die regte les waargeneem en dit verkeerd toegepas.","Hy het by sy keuses bygevoeg in plaas daarvan om van hulle af weg te draai."],"action":"Soek die verandering agter die les, nie net die gebaar nie.","detail":"Dink aan ’n teregwysing wat jy onlangs ontvang het. Vra watter werklike verandering dit vra, nie net wat beter sou lyk nie."},{"q":"Wat sê die Haftarah oor offers wat min kos?","ref":"28:9; Maleagi 1:7–8","answer":"In die Haftarah bestraf יהוה die priesters omdat hulle blinde en kreupel diere as offers bring, en vra of hulle goewerneur so ’n geskenk sou aanvaar.","key":["Esav het ook probeer behaag met iets wat hom min gekos het.","Om Elohim te behaag gaan nie oor ’n gebaar wat bygevoeg word nie, maar oor gee wat Hy gevra het."],"action":"Lees Maleagi 1:6–11 saam met Bereishit 28:6–9.","detail":"Skryf een terrein neer waar jy vir יהוה gee wat oorbly, in plaas van wat eerste en beste is."},{"q":"Probeer ek met byvoegings behaag in plaas van bekering?","ref":"28:9","answer":"Esav het Machalat geneem bo en behalwe die Hetitiese vroue wat sy ouers smart aangedoen het.","key":["Sy oplossing het die oorspronklike probleem laat staan.","Ek kan ’n godsdienstige gewoonte byvoeg sonder om los te laat wat Elohim bedroef."],"action":"Noem een ding wat jy bygevoeg het om jou gewete te sus.","detail":"Noem dan wat dit moes bedek. Bring daardie werklike saak eerlik voor יהוה."},{"q":"Sal ek gaan waarheen gehoorsaamheid my stuur?","ref":"28:5","answer":"Yitzchak het Yaakov weggestuur, en Yaakov het gegaan.","key":["Gehoorsaamheid beteken soms om te verlaat wat bekend is.","Hy het gegaan met die seën en die opdrag wat sy vader hom gegee het."],"action":"Neem hierdie week een tree in die rigting waarheen gehoorsaamheid jou wys.","detail":"Noem die skuif, gesprek of verbintenis waartoe jy weet jy geroep is. Stel ’n datum vir die eerste tree."}],"deeper":"Die Haftarah, Maleagi 1:1–2:7, begin waar hierdie Parashah eindig: יהוה verklaar dat Hy Yaakov liefgehad en Esav verwerp het, en dat Edom sal bou maar Hy sal afbreek (Maleagi 1:2–4). Daarna bestraf Hy die priesters wat sy Naam verag met gebrekkige offers (1:6–8), dieselfde tekortkoming as Esav, wat sy eersgeboortereg verag het (Bereishit 25:34), en hou Hy die verbond met Levi voor, in wie se mond die Torah van waarheid was (2:5–7). Paulus bring Bereishit 25:23 en Maleagi 1:2–3 saam in Romeine 9:10–13 om te wys dat die keuse berus op die voorneme van Elohim wat roep. Hebreërs 12:16–17 maak van die hele Parashah ’n waarskuwing: moenie wees soos Esav nie, wat sy eersgeboortereg vir een maaltyd verkoop het.","closing":"Esav het ’n vrou bygevoeg. Yaakov het gehoorsaam en gegaan.","actionOfDay":"Noem hierdie Shabbat een ding wat jy in jou lewe bygevoeg het om jou gewete te sus, in plaas daarvan om weg te draai van wat יהוה bedroef. Skryf die werklike tree van bekering neer, en neem dit op die eerste dag van die week.","waSummary":"Yaakov gehoorsaam sy ouers en vertrek, terwyl Esav nog ’n vrou neem om sy vader te behaag."}}];

